def residual_cylindrical_chain_endpoint_tfe_paper_lower_pair_acceleration_terminal_velocity_closure_candidate(
    x,
    z0_q,
    *args,
):
    out = residual_cylindrical_chain_endpoint_tfe_paper_lower_pair_acceleration_candidate(x, z0_q, *args)
    state0 = args[0]
    h = args[1]
    params_arrays = (args[4], args[5], args[6], args[7], args[8], args[9], args[10], args[11], args[12])
    r_end, p_end, terminal_z = paper_tfe_terminal_state_from_x_jax(x, state0)
    _, _, b = qp._gauss_legendre_coefficients_jax(N_STAGES, x.dtype)
    weighted_velocity_rows = jnp.sqrt(h * b[-1]) * endpoint_velocity_constraints_from_z_jax(
        r_end,
        p_end,
        terminal_z,
        params_arrays,
        x.dtype,
    )
    terminal_lower_pair0 = (N_STAGES - 1) * STAGE_SIZE + 4 * 3 * N_BODIES + 12
    return out.at[terminal_lower_pair0 : terminal_lower_pair0 + ENDPOINT_VELOCITY_CONSTRAINT_DIM].set(
        weighted_velocity_rows
    )


def residual_cylindrical_chain_endpoint_tfe_paper_lower_pair_acceleration_terminal_row_homotopy_candidate(
    x,
    z0_q,
    beta,
    *args,
):
    out = residual_cylindrical_chain_endpoint_tfe_paper_lower_pair_acceleration_candidate(x, z0_q, *args)
    state0 = args[0]
    h = args[1]
    params_arrays = (args[4], args[5], args[6], args[7], args[8], args[9], args[10], args[11], args[12])
    r_end, p_end, terminal_z = paper_tfe_terminal_state_from_x_jax(x, state0)
    _, _, b = qp._gauss_legendre_coefficients_jax(N_STAGES, x.dtype)
    weighted_velocity_rows = jnp.sqrt(h * b[-1]) * endpoint_velocity_constraints_from_z_jax(
        r_end,
        p_end,
        terminal_z,
        params_arrays,
        x.dtype,
    )
    terminal_lower_pair0 = (N_STAGES - 1) * STAGE_SIZE + 4 * 3 * N_BODIES + 12
    terminal_slice = slice(terminal_lower_pair0, terminal_lower_pair0 + ENDPOINT_VELOCITY_CONSTRAINT_DIM)
    acceleration_rows = out[terminal_slice]
    beta = jnp.asarray(beta, dtype=x.dtype)
    homotopy_rows = (1.0 - beta) * acceleration_rows + beta * weighted_velocity_rows
    return out.at[terminal_slice].set(homotopy_rows)


