def paper_tfe_lower_pair_source_free_mean_velocity_closure_rows_jax(x, z0_q, *args):
    h = args[1]
    _, _, b = qp._gauss_legendre_coefficients_jax(N_STAGES, x.dtype)
    acceleration_rows = paper_tfe_lower_pair_acceleration_stage_rows_jax(x, *args).reshape(
        (N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM)
    )
    velocity_rows = paper_tfe_lower_pair_velocity_stage_rows_jax(x, *args).reshape(
        (N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM)
    )
    source_estimates = []
    for si in range(N_STAGES):
        source_estimates.append(acceleration_rows[si] / jnp.sqrt(h * b[si]))
    source_estimates = jnp.stack(source_estimates)
    centered_acceleration_rows = []
    for si in range(1, N_STAGES):
        centered_acceleration_rows.append(jnp.sqrt(h * b[si]) * (source_estimates[si] - source_estimates[0]))
    mean_velocity_closure = sum(jnp.sqrt(b[si]) * velocity_rows[si] for si in range(N_STAGES))
    return jnp.concatenate(centered_acceleration_rows + [mean_velocity_closure])


