def paper_tfe_lower_pair_source_free_recurrent_weak_closure_rows_jax(x, z0_q, history_source, *args):
    h = args[1]
    _, _, b = qp._gauss_legendre_coefficients_jax(N_STAGES, x.dtype)
    acceleration_rows = paper_tfe_lower_pair_acceleration_stage_rows_jax(x, *args).reshape(
        (N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM)
    )
    velocity_rows = paper_tfe_lower_pair_velocity_stage_rows_jax(x, *args).reshape(
        (N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM)
    )
    source_estimates = []
    for si in range(N_STAGES):
        source_estimates.append(acceleration_rows[si] / jnp.sqrt(h * b[si]))
    source_estimates = jnp.stack(source_estimates)
    centered_acceleration_rows = []
    for si in range(1, N_STAGES):
        centered_acceleration_rows.append(jnp.sqrt(h * b[si]) * (source_estimates[si] - source_estimates[0]))

    history = jnp.asarray(history_source, dtype=x.dtype).reshape((ENDPOINT_VELOCITY_CONSTRAINT_DIM,))
    source_curvature = source_estimates[2] - 2.0 * source_estimates[1] + source_estimates[0]
    recurrent_source_delta = source_estimates[0] - history
    bounded_feature = jnp.tanh(source_curvature + recurrent_source_delta)
    feature_norm = jnp.sqrt(jnp.sum(bounded_feature * bounded_feature) + jnp.asarray(1e-30, dtype=x.dtype))
    normalized_feature = bounded_feature / (1.0 + feature_norm)

    nonfinal_weights = jnp.stack([jnp.sqrt(b[0]), jnp.sqrt(b[1])])
    nonfinal_weights = nonfinal_weights / jnp.sum(nonfinal_weights)
    nonfinal_velocity_closure = nonfinal_weights[0] * velocity_rows[0] + nonfinal_weights[1] * velocity_rows[1]
    mean_acceleration_closure = sum(jnp.sqrt(b[si]) * acceleration_rows[si] for si in range(N_STAGES))
    recurrent_weight = jnp.tanh(h * feature_norm)
    recurrent_weak_closure = (
        (1.0 - recurrent_weight) * mean_acceleration_closure
        + recurrent_weight * nonfinal_velocity_closure
        + h * normalized_feature
    )
    return jnp.concatenate(centered_acceleration_rows + [recurrent_weak_closure])


def residual_cylindrical_chain_endpoint_tfe_paper_lower_pair_source_free_recurrent_weak_closure_candidate(
    x,
    z0_q,
    history_source,
    *args,
):
    out = residual_cylindrical_chain_endpoint_tfe_paper_lower_pair_acceleration_candidate(x, z0_q, *args)
    lower_pair_rows = paper_tfe_lower_pair_source_free_recurrent_weak_closure_rows_jax(
        x,
        z0_q,
        history_source,
        *args,
    ).reshape((N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM))
    for si in range(N_STAGES):
        lower0 = si * STAGE_SIZE + 4 * 3 * N_BODIES + 12
        out = out.at[lower0 : lower0 + ENDPOINT_VELOCITY_CONSTRAINT_DIM].set(lower_pair_rows[si])
    return out


def paper_tfe_lower_pair_source_free_recurrent_terminal_blend_rows_jax(x, z0_q, history_source, gamma, *args):
    recurrent_rows = paper_tfe_lower_pair_source_free_recurrent_weak_closure_rows_jax(
        x,
        z0_q,
        history_source,
        *args,
    ).reshape((N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM))
    final_stage_rows = paper_tfe_lower_pair_source_free_final_stage_velocity_closure_rows_jax(
        x,
        z0_q,
        *args,
    ).reshape((N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM))
    gamma_value = jnp.asarray(gamma, dtype=x.dtype)
    closure_rows = (1.0 - gamma_value) * recurrent_rows[N_STAGES - 1] + gamma_value * final_stage_rows[N_STAGES - 1]
    return jnp.concatenate([recurrent_rows[0], recurrent_rows[1], closure_rows])


