def paper_tfe_lower_pair_source_free_terminal_extrapolation_blend_closure_rows_jax(
    x,
    z0_q,
    alpha,
    beta,
    *args,
):
    mean_blend_rows = paper_tfe_lower_pair_source_free_mean_blend_closure_rows_jax(
        x,
        z0_q,
        alpha,
        *args,
    )
    terminal_extrapolation_rows = (
        paper_tfe_lower_pair_source_free_terminal_velocity_extrapolation_closure_rows_jax(
            x,
            z0_q,
            *args,
        )
    )
    mean0 = (N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM
    beta_value = jnp.asarray(beta, dtype=x.dtype)
    blended_closure = (1.0 - beta_value) * mean_blend_rows[mean0:] + beta_value * terminal_extrapolation_rows[mean0:]
    return jnp.concatenate([mean_blend_rows[:mean0], blended_closure])


