def residual_cylindrical_chain_initial_acceleration_z0(y, *args):
    state0 = args[0]
    masses = args[2]
    Js = args[3]
    s_prev = args[4]
    s_next = args[5]
    axis_prev = args[6]
    axis_next = args[7]
    twist_prev = args[8]
    twist_next = args[9]
    ground_axis = args[10]
    ground_twist = args[11]
    joint_basis = args[12]
    gravity = args[13]
    external_forces_world = args[14]
    external_torques_body = args[15]
    mu_s = args[16]
    mu_d = args[17]
    stribeck_velocity = args[18]
    viscous_damping = args[19]
    friction_radius = args[20]
    r0, p0, v0, w0 = state0
    a = y[: 3 * N_BODIES].reshape((N_BODIES, 3))
    alpha = y[3 * N_BODIES : 6 * N_BODIES].reshape((N_BODIES, 3))
    lam = y[6 * N_BODIES :].reshape((N_JOINTS, LAMBDA_SIZE))
    params_arrays = (s_prev, s_next, axis_prev, axis_next, twist_prev, twist_next, ground_axis, ground_twist, joint_basis)
    R = [qp.quat_to_rot_jax(p0[i]) for i in range(N_BODIES)]
    st = {"r": r0, "v": v0, "w": w0, "a": a, "alpha": alpha}
    kin = joint_kinematics_jax(st, R, params_arrays, y.dtype) | {"R": R}
    joint_force = []
    for joint in range(N_JOINTS):
        normal_force = lam[joint, 0] * joint_basis[joint, 0] + lam[joint, 1] * joint_basis[joint, 1]
        normal_load = jnp.sqrt(normal_force @ normal_force + jnp.array(1.0e-24, dtype=y.dtype))
        slide_vel = kin["rel_vel"][joint] @ kin["parent_axis"][joint]
        friction = brown_mcphee_scalar_jax(
            slide_vel,
            normal_load,
            mu_s,
            mu_d,
            stribeck_velocity,
            viscous_damping,
            friction_radius,
        )
        joint_force.append(normal_force + friction * kin["parent_axis"][joint])

    dyn = []
    for body in range(N_BODIES):
        force = joint_force[body]
        if body == 0:
            force = force - joint_force[1]
        trans = masses[body] * a[body] - masses[body] * gravity - external_forces_world[body] - force
        prox_torque = jnp.cross(s_prev[body], R[body].T @ joint_force[body])
        if body == 0:
            distal_torque = jnp.cross(s_next[0], R[0].T @ (-joint_force[1]))
        else:
            distal_torque = jnp.zeros(3, dtype=y.dtype)
        eta_prox = lam[body, 2:4]
        axis_torque = eta_prox[0] * jnp.cross(axis_prev[body], R[body].T @ joint_basis[body, 0])
        axis_torque += eta_prox[1] * jnp.cross(axis_prev[body], R[body].T @ joint_basis[body, 1])
        if body == 0:
            eta_dist = lam[1, 2:4]
            dist_axis_torque = eta_dist[0] * jnp.cross(axis_next[0], R[0].T @ joint_basis[1, 0])
            dist_axis_torque += eta_dist[1] * jnp.cross(axis_next[0], R[0].T @ joint_basis[1, 1])
        else:
            dist_axis_torque = jnp.zeros(3, dtype=y.dtype)
        rot = (
            Js[body] @ alpha[body]
            + jnp.cross(w0[body], Js[body] @ w0[body])
            - prox_torque
            - distal_torque
            - axis_torque
            + dist_axis_torque
            - external_torques_body[body]
        )
        dyn.extend([trans, rot])

    acceleration_constraints = []
    for joint in range(N_JOINTS):
        acceleration_constraints.append(
            jnp.asarray(
                [
                    kin["rel_acc"][joint] @ joint_basis[joint, 0],
                    kin["rel_acc"][joint] @ joint_basis[joint, 1],
                ],
                dtype=y.dtype,
            )
        )
        acceleration_constraints.append(kin["axis_acc"][joint])
    return jnp.concatenate([jnp.concatenate(dyn), jnp.concatenate(acceleration_constraints)])


