def residual_cylindrical_chain_endpoint_tfe_stage_weighted_candidate(y, *args):
    x = y[:DIM]
    q0 = DIM
    z0 = q0 + ENDPOINT_POSITION_DIM
    pos_eta0 = z0 + ENDPOINT_VELOCITY_DIM
    vel_eta0 = pos_eta0 + ENDPOINT_POSITION_CONSTRAINT_DIM
    endpoint_q = y[q0:z0]
    endpoint_z = y[z0:pos_eta0]
    endpoint_pos_eta = y[pos_eta0:vel_eta0]
    endpoint_vel_eta = y[vel_eta0:]
    unweighted_stage_residual = residual_cylindrical_chain(x, *args)
    state0 = args[0]
    h = args[1]
    params_arrays = (args[4], args[5], args[6], args[7], args[8], args[9], args[10], args[11], args[12])
    stages = unpack_stages(x)
    raw_r_end, raw_p_end, v_raw, w_raw = endpoint_state_from_stages_jax(stages, state0, h)
    r_end, p_end = endpoint_pose_from_q_jax(raw_r_end, raw_p_end, endpoint_q)
    raw_z = jnp.concatenate([v_raw.reshape(-1), w_raw.reshape(-1)])
    endpoint_weight = jnp.sqrt(h)
    stage_weight = stage_quadrature_weight_vector(h, y.dtype)
    position_constraints = endpoint_position_constraints_from_q_jax(raw_r_end, raw_p_end, endpoint_q, params_arrays, y.dtype)
    position_matrix = ENDPOINT_POSITION_Q_JAC(endpoint_q, raw_r_end, raw_p_end, *params_arrays)
    velocity_constraints = endpoint_velocity_constraints_from_z_jax(r_end, p_end, endpoint_z, params_arrays, y.dtype)
    velocity_matrix = endpoint_velocity_matrix_jax(r_end, p_end, params_arrays, y.dtype)
    position_stationarity = endpoint_q + endpoint_weight * (position_matrix.T @ endpoint_pos_eta)
    velocity_stationarity = endpoint_z - raw_z + endpoint_weight * (velocity_matrix.T @ endpoint_vel_eta)
    return jnp.concatenate(
        [
            stage_weight * unweighted_stage_residual,
            position_stationarity,
            velocity_stationarity,
            endpoint_weight * position_constraints,
            endpoint_weight * velocity_constraints,
        ]
    )


R_ENDPOINT_TFE_STAGE_WEIGHTED_VALUE = jax.jit(residual_cylindrical_chain_endpoint_tfe_stage_weighted_candidate)
R_ENDPOINT_TFE_STAGE_WEIGHTED_JAC = jax.jit(jax.jacfwd(residual_cylindrical_chain_endpoint_tfe_stage_weighted_candidate, argnums=0))


def stage_non_equivalent_probe_stage_major_jax(
    endpoint_q,
    endpoint_velocity_delta,
    raw_position_constraints,
    raw_velocity_constraints,
    h,
    masses,
    Js,
    x_dtype,
):
    _, _, b = qp._gauss_legendre_coefficients_jax(N_STAGES, x_dtype)
    q_r = endpoint_q[: 3 * N_BODIES]
    q_u = endpoint_q[3 * N_BODIES :]
    delta_v = endpoint_velocity_delta[: 3 * N_BODIES].reshape((N_BODIES, 3))
    delta_w = endpoint_velocity_delta[3 * N_BODIES :].reshape((N_BODIES, 3))
    dyn_seed = []
    for body in range(N_BODIES):
        dyn_seed.extend([masses[body] * delta_v[body], Js[body] @ delta_w[body]])
    dyn_seed_flat = jnp.concatenate(dyn_seed)
    constraint_seed = raw_position_constraints + h * raw_velocity_constraints
    rows = []
    for si in range(N_STAGES):
        weight = jnp.sqrt(h * b[si])
        rows.extend(
            [
                weight * q_r,
                weight * q_u,
                weight * endpoint_velocity_delta[: 3 * N_BODIES],
                weight * endpoint_velocity_delta[3 * N_BODIES :],
                weight * dyn_seed_flat,
                weight * constraint_seed,
            ]
        )
    return jnp.concatenate(rows)


def residual_cylindrical_chain_endpoint_tfe_stage_non_equivalent_solved_probe(y, *args):
    x = y[:DIM]
    q0 = DIM
    z0 = q0 + ENDPOINT_POSITION_DIM
    pos_eta0 = z0 + ENDPOINT_VELOCITY_DIM
    vel_eta0 = pos_eta0 + ENDPOINT_POSITION_CONSTRAINT_DIM
    endpoint_q = y[q0:z0]
    endpoint_z = y[z0:pos_eta0]
    endpoint_pos_eta = y[pos_eta0:vel_eta0]
    endpoint_vel_eta = y[vel_eta0:]
    unweighted_stage_residual = residual_cylindrical_chain(x, *args)
    state0 = args[0]
    h = args[1]
    masses = args[2]
    Js = args[3]
    params_arrays = (args[4], args[5], args[6], args[7], args[8], args[9], args[10], args[11], args[12])
    stages = unpack_stages(x)
    raw_r_end, raw_p_end, v_raw, w_raw = endpoint_state_from_stages_jax(stages, state0, h)
    r_end, p_end = endpoint_pose_from_q_jax(raw_r_end, raw_p_end, endpoint_q)
    raw_z = jnp.concatenate([v_raw.reshape(-1), w_raw.reshape(-1)])
    endpoint_velocity_delta = endpoint_z - raw_z
    endpoint_weight = jnp.sqrt(h)
    stage_weight = stage_quadrature_weight_vector(h, y.dtype)
    zero_q = jnp.zeros_like(endpoint_q)
    raw_position_constraints = endpoint_position_constraints_from_q_jax(raw_r_end, raw_p_end, zero_q, params_arrays, y.dtype)
    raw_velocity_constraints = endpoint_velocity_constraints_from_z_jax(raw_r_end, raw_p_end, raw_z, params_arrays, y.dtype)
    non_equivalent_stage_probe = stage_non_equivalent_probe_stage_major_jax(
        endpoint_q,
        endpoint_velocity_delta,
        raw_position_constraints,
        raw_velocity_constraints,
        h,
        masses,
        Js,
        y.dtype,
    )
    position_constraints = endpoint_position_constraints_from_q_jax(raw_r_end, raw_p_end, endpoint_q, params_arrays, y.dtype)
    position_matrix = ENDPOINT_POSITION_Q_JAC(endpoint_q, raw_r_end, raw_p_end, *params_arrays)
    velocity_constraints = endpoint_velocity_constraints_from_z_jax(r_end, p_end, endpoint_z, params_arrays, y.dtype)
    velocity_matrix = endpoint_velocity_matrix_jax(r_end, p_end, params_arrays, y.dtype)
    position_stationarity = endpoint_q + endpoint_weight * (position_matrix.T @ endpoint_pos_eta)
    velocity_stationarity = endpoint_z - raw_z + endpoint_weight * (velocity_matrix.T @ endpoint_vel_eta)
    return jnp.concatenate(
        [
            stage_weight * unweighted_stage_residual + non_equivalent_stage_probe,
            position_stationarity,
            velocity_stationarity,
            endpoint_weight * position_constraints,
            endpoint_weight * velocity_constraints,
        ]
    )


