def paper_all_row_balance_constraint_rows_np(candidate_residual: np.ndarray) -> np.ndarray:
    pieces = []
    for stage in range(N_STAGES):
        base = stage * STAGE_SIZE + 4 * 3 * N_BODIES
        pieces.append(candidate_residual[base : base + 20])
    return np.concatenate(pieces)


def endpoint_tfe_paper_all_row_substitution_candidate_step(state: State, params: Params, h: float = H):
    x = stage_guess(state, h, params)
    args = build_args(state, h, params)
    total_residual = 0.0
    total_jac = 0.0
    total_linear = 0.0
    max_linear_residual = 0.0
    max_jacobian_condition = 0.0
    min_jacobian_rank = DIM
    last_norm = np.inf
    for it in range(80):
        x_jax = jnp.asarray(x, dtype=jnp.float64)
        started = time.perf_counter()
        res = np.asarray(R_ENDPOINT_TFE_PAPER_ALL_ROW_SUBSTITUTION_VALUE(x_jax, *args), dtype=float)
        total_residual += time.perf_counter() - started
        last_norm = float(np.linalg.norm(res))
        if last_norm < 1.0e-11:
            break
        started = time.perf_counter()
        jac = np.asarray(R_ENDPOINT_TFE_PAPER_ALL_ROW_SUBSTITUTION_JAC(x_jax, *args), dtype=float)
        total_jac += time.perf_counter() - started
        min_jacobian_rank = min(min_jacobian_rank, int(np.linalg.matrix_rank(jac, tol=1.0e-10)))
        max_jacobian_condition = max(max_jacobian_condition, float(np.linalg.cond(jac)))
        started = time.perf_counter()
        delta = np.linalg.solve(jac, -res)
        total_linear += time.perf_counter() - started
        max_linear_residual = max(max_linear_residual, float(np.linalg.norm(jac @ delta + res)))
        x = x + delta
        if float(np.linalg.norm(delta)) < 1.0e-11:
            x_jax = jnp.asarray(x, dtype=jnp.float64)
            res = np.asarray(R_ENDPOINT_TFE_PAPER_ALL_ROW_SUBSTITUTION_VALUE(x_jax, *args), dtype=float)
            last_norm = float(np.linalg.norm(res))
            break
    else:
        raise RuntimeError(f"paper all-row substitution Newton failed residual={last_norm:.3e}")
    stages = unpack_stages(x)
    next_state = next_state_from_stages(state, h, stages, params, project_velocity=True)
    con, vel = constraint_parts_np(next_state, params, h)
    candidate_res = np.asarray(
        R_ENDPOINT_TFE_PAPER_ALL_ROW_SUBSTITUTION_VALUE(jnp.asarray(x, dtype=jnp.float64), *args),
        dtype=float,
    )
    gauss_res = np.asarray(R_VALUE(jnp.asarray(x, dtype=jnp.float64), *args), dtype=float)
    paper_kinematic_rows = paper_kinematic_substitution_stage_rows_np(candidate_res)
    paper_balance_constraint_rows = paper_all_row_balance_constraint_rows_np(candidate_res)
    removed_gauss_rows = gauss_res
    diag = {
        "newton_iterations": it + 1,
        "total_residual_eval_sec": total_residual,
        "total_jacobian_eval_sec": total_jac,
        "total_linear_solve_sec": total_linear,
        "max_linear_residual_norm": max_linear_residual,
        "max_paper_all_row_substitution_residual_norm": float(np.linalg.norm(candidate_res)),
        "max_paper_kinematic_row_norm": float(np.linalg.norm(paper_kinematic_rows)),
        "max_paper_balance_constraint_row_norm": float(np.linalg.norm(paper_balance_constraint_rows)),
        "max_removed_gauss_all_row_block_norm": float(np.linalg.norm(removed_gauss_rows)),
        "max_endpoint_constraint_norm": float(np.linalg.norm(con)),
        "max_endpoint_velocity_constraint_norm": float(np.linalg.norm(vel)),
        "min_jacobian_rank": min_jacobian_rank,
        "max_jacobian_condition": max_jacobian_condition,
        "max_quaternion_unit_error": float(np.max(np.abs(np.linalg.norm(next_state.p, axis=1) - 1.0))),
    }
    return next_state, diag


