def endpoint_tfe_paper_lower_pair_source_free_order_closure_blend_step(
    state: State,
    params: Params,
    previous_terminal_z0: np.ndarray,
    beta: float,
    h: float = H,
    linear_solve_policy: str = "iterative_equilibrated",
):
    x_gauss, _ = solve_gauss_stage_x(state, params, h)
    used_z0 = np.asarray(previous_terminal_z0, dtype=float)
    x = np.asarray(x_gauss, dtype=float).copy()
    z0_jax = jnp.asarray(used_z0, dtype=jnp.float64)
    beta_jax = jnp.asarray(float(beta), dtype=jnp.float64)
    args = build_args(state, h, params)
    total_residual = 0.0
    total_jac = 0.0
    total_linear = 0.0
    max_raw_linear_residual = 0.0
    max_scaled_linear_residual = 0.0
    max_raw_jacobian_condition = 0.0
    max_scaled_jacobian_condition = 0.0
    max_condition_reduction_raw_to_scaled = 0.0
    min_jacobian_rank = DIM
    final_norm = float("inf")
    newton_converged = False
    for it in range(80):
        x_jax = jnp.asarray(x, dtype=jnp.float64)
        started = time.perf_counter()
        res = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ORDER_CLOSURE_BLEND_VALUE(
                x_jax,
                z0_jax,
                beta_jax,
                *args,
            ),
            dtype=float,
        )
        total_residual += time.perf_counter() - started
        final_norm = float(np.linalg.norm(res))
        if final_norm < 1.0e-11:
            newton_converged = True
            break
        if not np.isfinite(final_norm) or final_norm > 1.0e8:
            raise RuntimeError(f"source-free order/closure blend residual diverged: {final_norm:.3e}")
        started = time.perf_counter()
        jac = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ORDER_CLOSURE_BLEND_JAC(
                x_jax,
                z0_jax,
                beta_jax,
                *args,
            ),
            dtype=float,
        )
        total_jac += time.perf_counter() - started
        rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
        raw_condition = float(np.linalg.cond(jac))
        min_jacobian_rank = min(min_jacobian_rank, rank)
        max_raw_jacobian_condition = max(max_raw_jacobian_condition, raw_condition)
        started = time.perf_counter()
        delta, linear_diag = solve_newton_linear_system_np(jac, res, linear_solve_policy)
        total_linear += time.perf_counter() - started
        max_raw_linear_residual = max(max_raw_linear_residual, linear_diag["raw_linear_residual_norm"])
        max_scaled_linear_residual = max(max_scaled_linear_residual, linear_diag["scaled_linear_residual_norm"])
        max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, linear_diag["scaled_jacobian_condition"])
        max_condition_reduction_raw_to_scaled = max(
            max_condition_reduction_raw_to_scaled,
            linear_diag["condition_reduction_raw_to_scaled"],
        )
        x = x + delta
        if float(np.linalg.norm(delta)) < 1.0e-11:
            x_jax = jnp.asarray(x, dtype=jnp.float64)
            res = np.asarray(
                R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ORDER_CLOSURE_BLEND_VALUE(
                    x_jax,
                    z0_jax,
                    beta_jax,
                    *args,
                ),
                dtype=float,
            )
            final_norm = float(np.linalg.norm(res))
            newton_converged = final_norm < 1.0e-10
            break

    x_jax = jnp.asarray(x, dtype=jnp.float64)
    started = time.perf_counter()
    candidate_res = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ORDER_CLOSURE_BLEND_VALUE(
            x_jax,
            z0_jax,
            beta_jax,
            *args,
        ),
        dtype=float,
    )
    total_residual += time.perf_counter() - started
    final_norm = float(np.linalg.norm(candidate_res))
    started = time.perf_counter()
    jac = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ORDER_CLOSURE_BLEND_JAC(
            x_jax,
            z0_jax,
            beta_jax,
            *args,
        ),
        dtype=float,
    )
    total_jac += time.perf_counter() - started
    final_rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
    final_raw_condition = float(np.linalg.cond(jac))
    final_scaled_condition = scaled_condition_np(jac, "iterative")
    min_jacobian_rank = min(min_jacobian_rank, final_rank)
    max_raw_jacobian_condition = max(max_raw_jacobian_condition, final_raw_condition)
    max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, final_scaled_condition)
    max_condition_reduction_raw_to_scaled = max(
        max_condition_reduction_raw_to_scaled,
        final_raw_condition / max(final_scaled_condition, 1.0e-300),
    )
    newton_converged = bool(newton_converged or final_norm < 1.0e-10)

    stages = unpack_stages(x)
    terminal_z0 = paper_tfe_terminal_z_from_stages(stages)
    terminal_output_raw = paper_tfe_terminal_state_from_stages(state, stages, params=None, project_velocity=False)
    gauss_output_raw = next_state_from_stages(state, h, stages, params=None, project_velocity=False)
    raw_con, raw_vel = constraint_parts_np(terminal_output_raw, params, h)
    paper_kinematic_rows = paper_kinematic_substitution_stage_rows_np(candidate_res)
    paper_newton_euler_rows = stage_residual_block_np(candidate_res, "newton_euler_weak_balance")
    paper_lower_pair_rows = stage_residual_block_np(candidate_res, "lower_pair_index3_weak_constraints")
    source_consistency_rows = paper_lower_pair_rows[: (N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM]
    order_closure_blend_rows = paper_lower_pair_rows[(N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM :]
    return terminal_output_raw, terminal_z0, {
        "newton_iterations": it + 1,
        "newton_converged": newton_converged,
        "total_residual_eval_sec": total_residual,
        "total_jacobian_eval_sec": total_jac,
        "total_linear_solve_sec": total_linear,
        "residual_norm": final_norm,
        "max_paper_kinematic_row_norm": float(np.linalg.norm(paper_kinematic_rows)),
        "max_paper_newton_euler_row_norm": float(np.linalg.norm(paper_newton_euler_rows)),
        "max_source_free_lower_pair_row_norm": float(np.linalg.norm(paper_lower_pair_rows)),
        "max_source_consistency_row_norm": float(np.linalg.norm(source_consistency_rows)),
        "max_order_closure_blend_closure_row_norm": float(np.linalg.norm(order_closure_blend_rows)),
        "max_raw_terminal_endpoint_constraint_norm": float(np.linalg.norm(raw_con)),
        "max_raw_terminal_endpoint_velocity_constraint_norm": float(np.linalg.norm(raw_vel)),
        "max_terminal_vs_gauss_position_delta_norm": float(np.linalg.norm(terminal_output_raw.r - gauss_output_raw.r)),
        "max_terminal_vs_gauss_velocity_delta_norm": float(np.linalg.norm(terminal_output_raw.v - gauss_output_raw.v)),
        "min_jacobian_rank": min_jacobian_rank,
        "max_raw_jacobian_condition": max_raw_jacobian_condition,
        "max_scaled_jacobian_condition": max_scaled_jacobian_condition,
        "max_condition_reduction_raw_to_scaled": max_condition_reduction_raw_to_scaled,
        "max_raw_linear_residual_norm": max_raw_linear_residual,
        "max_scaled_linear_residual_norm": max_scaled_linear_residual,
        "max_terminal_z0_update_delta_norm": float(np.linalg.norm(terminal_z0 - used_z0)),
        "max_terminal_z0_norm": float(np.linalg.norm(terminal_z0)),
        "linear_solve_policy": linear_solve_policy,
    }


def paper_tfe_lower_pair_stage0_source_history_np(x: np.ndarray, h: float, args: tuple) -> tuple[np.ndarray, dict[str, float]]:
    x_jax = jnp.asarray(x, dtype=jnp.float64)
    acceleration_rows = np.asarray(
        paper_tfe_lower_pair_acceleration_stage_rows_jax(x_jax, *args),
        dtype=float,
    ).reshape((N_STAGES, ENDPOINT_VELOCITY_CONSTRAINT_DIM))
    _, _, b_jax = qp._gauss_legendre_coefficients_jax(N_STAGES, jnp.float64)
    b = np.asarray(b_jax, dtype=float)
    source_estimates = acceleration_rows / np.sqrt(h * b)[:, None]
    source_curvature = source_estimates[2] - 2.0 * source_estimates[1] + source_estimates[0]
    return np.asarray(source_estimates[0], dtype=float), {
        "stage0_source_norm": float(np.linalg.norm(source_estimates[0])),
        "mean_source_norm": float(np.linalg.norm(np.mean(source_estimates, axis=0))),
        "source_curvature_norm": float(np.linalg.norm(source_curvature)),
    }


def endpoint_tfe_paper_lower_pair_source_free_recurrent_weak_closure_step(
    state: State,
    params: Params,
    previous_terminal_z0: np.ndarray,
    history_source: np.ndarray,
    h: float = H,
    linear_solve_policy: str = "iterative_equilibrated",
):
    x_gauss, _ = solve_gauss_stage_x(state, params, h)
    used_z0 = np.asarray(previous_terminal_z0, dtype=float)
    used_history_source = np.asarray(history_source, dtype=float).reshape((ENDPOINT_VELOCITY_CONSTRAINT_DIM,))
    x = np.asarray(x_gauss, dtype=float).copy()
    z0_jax = jnp.asarray(used_z0, dtype=jnp.float64)
    history_source_jax = jnp.asarray(used_history_source, dtype=jnp.float64)
    args = build_args(state, h, params)
    total_residual = 0.0
    total_jac = 0.0
    total_linear = 0.0
    max_raw_linear_residual = 0.0
    max_scaled_linear_residual = 0.0
    max_raw_jacobian_condition = 0.0
    max_scaled_jacobian_condition = 0.0
    max_condition_reduction_raw_to_scaled = 0.0
    min_jacobian_rank = DIM
    final_norm = float("inf")
    newton_converged = False
    for it in range(80):
        x_jax = jnp.asarray(x, dtype=jnp.float64)
        started = time.perf_counter()
        res = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_WEAK_CLOSURE_VALUE(
                x_jax,
                z0_jax,
                history_source_jax,
                *args,
            ),
            dtype=float,
        )
        total_residual += time.perf_counter() - started
        final_norm = float(np.linalg.norm(res))
        if final_norm < 1.0e-11:
            newton_converged = True
            break
        if not np.isfinite(final_norm) or final_norm > 1.0e8:
            raise RuntimeError(f"source-free recurrent weak closure residual diverged: {final_norm:.3e}")
        started = time.perf_counter()
        jac = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_WEAK_CLOSURE_JAC(
                x_jax,
                z0_jax,
                history_source_jax,
                *args,
            ),
            dtype=float,
        )
        total_jac += time.perf_counter() - started
        rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
        raw_condition = float(np.linalg.cond(jac))
        min_jacobian_rank = min(min_jacobian_rank, rank)
        max_raw_jacobian_condition = max(max_raw_jacobian_condition, raw_condition)
        started = time.perf_counter()
        delta, linear_diag = solve_newton_linear_system_np(jac, res, linear_solve_policy)
        total_linear += time.perf_counter() - started
        max_raw_linear_residual = max(max_raw_linear_residual, linear_diag["raw_linear_residual_norm"])
        max_scaled_linear_residual = max(max_scaled_linear_residual, linear_diag["scaled_linear_residual_norm"])
        max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, linear_diag["scaled_jacobian_condition"])
        max_condition_reduction_raw_to_scaled = max(
            max_condition_reduction_raw_to_scaled,
            linear_diag["condition_reduction_raw_to_scaled"],
        )
        x = x + delta
        if float(np.linalg.norm(delta)) < 1.0e-11:
            x_jax = jnp.asarray(x, dtype=jnp.float64)
            res = np.asarray(
                R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_WEAK_CLOSURE_VALUE(
                    x_jax,
                    z0_jax,
                    history_source_jax,
                    *args,
                ),
                dtype=float,
            )
            final_norm = float(np.linalg.norm(res))
            newton_converged = final_norm < 1.0e-10
            break

    x_jax = jnp.asarray(x, dtype=jnp.float64)
    started = time.perf_counter()
    candidate_res = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_WEAK_CLOSURE_VALUE(
            x_jax,
            z0_jax,
            history_source_jax,
            *args,
        ),
        dtype=float,
    )
    total_residual += time.perf_counter() - started
    final_norm = float(np.linalg.norm(candidate_res))
    started = time.perf_counter()
    jac = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_WEAK_CLOSURE_JAC(
            x_jax,
            z0_jax,
            history_source_jax,
            *args,
        ),
        dtype=float,
    )
    total_jac += time.perf_counter() - started
    final_rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
    final_raw_condition = float(np.linalg.cond(jac))
    final_scaled_condition = scaled_condition_np(jac, "iterative")
    min_jacobian_rank = min(min_jacobian_rank, final_rank)
    max_raw_jacobian_condition = max(max_raw_jacobian_condition, final_raw_condition)
    max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, final_scaled_condition)
    max_condition_reduction_raw_to_scaled = max(
        max_condition_reduction_raw_to_scaled,
        final_raw_condition / max(final_scaled_condition, 1.0e-300),
    )
    newton_converged = bool(newton_converged or final_norm < 1.0e-10)

    stages = unpack_stages(x)
    terminal_z0 = paper_tfe_terminal_z_from_stages(stages)
    terminal_output_raw = paper_tfe_terminal_state_from_stages(state, stages, params=None, project_velocity=False)
    gauss_output_raw = next_state_from_stages(state, h, stages, params=None, project_velocity=False)
    raw_con, raw_vel = constraint_parts_np(terminal_output_raw, params, h)
    paper_kinematic_rows = paper_kinematic_substitution_stage_rows_np(candidate_res)
    paper_newton_euler_rows = stage_residual_block_np(candidate_res, "newton_euler_weak_balance")
    paper_lower_pair_rows = stage_residual_block_np(candidate_res, "lower_pair_index3_weak_constraints")
    source_consistency_rows = paper_lower_pair_rows[: (N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM]
    recurrent_weak_rows = paper_lower_pair_rows[(N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM :]
    next_history_source, history_diag = paper_tfe_lower_pair_stage0_source_history_np(x, h, args)
    return terminal_output_raw, terminal_z0, next_history_source, {
        "newton_iterations": it + 1,
        "newton_converged": newton_converged,
        "total_residual_eval_sec": total_residual,
        "total_jacobian_eval_sec": total_jac,
        "total_linear_solve_sec": total_linear,
        "residual_norm": final_norm,
        "max_paper_kinematic_row_norm": float(np.linalg.norm(paper_kinematic_rows)),
        "max_paper_newton_euler_row_norm": float(np.linalg.norm(paper_newton_euler_rows)),
        "max_source_free_lower_pair_row_norm": float(np.linalg.norm(paper_lower_pair_rows)),
        "max_source_consistency_row_norm": float(np.linalg.norm(source_consistency_rows)),
        "max_recurrent_weak_closure_row_norm": float(np.linalg.norm(recurrent_weak_rows)),
        "max_raw_terminal_endpoint_constraint_norm": float(np.linalg.norm(raw_con)),
        "max_raw_terminal_endpoint_velocity_constraint_norm": float(np.linalg.norm(raw_vel)),
        "max_terminal_vs_gauss_position_delta_norm": float(np.linalg.norm(terminal_output_raw.r - gauss_output_raw.r)),
        "max_terminal_vs_gauss_velocity_delta_norm": float(np.linalg.norm(terminal_output_raw.v - gauss_output_raw.v)),
        "min_jacobian_rank": min_jacobian_rank,
        "max_raw_jacobian_condition": max_raw_jacobian_condition,
        "max_scaled_jacobian_condition": max_scaled_jacobian_condition,
        "max_condition_reduction_raw_to_scaled": max_condition_reduction_raw_to_scaled,
        "max_raw_linear_residual_norm": max_raw_linear_residual,
        "max_scaled_linear_residual_norm": max_scaled_linear_residual,
        "max_terminal_z0_update_delta_norm": float(np.linalg.norm(terminal_z0 - used_z0)),
        "max_terminal_z0_norm": float(np.linalg.norm(terminal_z0)),
        "history_source_norm": float(np.linalg.norm(used_history_source)),
        "next_history_source_norm": float(np.linalg.norm(next_history_source)),
        "history_source_update_norm": float(np.linalg.norm(next_history_source - used_history_source)),
        "stage0_source_norm": history_diag["stage0_source_norm"],
        "mean_source_norm": history_diag["mean_source_norm"],
        "source_curvature_norm": history_diag["source_curvature_norm"],
        "history_source_bootstrap_policy": "zero_initial_then_stage0_source_estimate",
        "linear_solve_policy": linear_solve_policy,
        "stage_x": x.copy(),
        "used_z0": used_z0.copy(),
        "used_history_source": used_history_source.copy(),
    }


def endpoint_tfe_paper_lower_pair_source_free_recurrent_terminal_blend_step(
    state: State,
    params: Params,
    previous_terminal_z0: np.ndarray,
    history_source: np.ndarray,
    gamma: float,
    h: float = H,
    linear_solve_policy: str = "iterative_equilibrated",
):
    x_gauss, _ = solve_gauss_stage_x(state, params, h)
    used_z0 = np.asarray(previous_terminal_z0, dtype=float)
    used_history_source = np.asarray(history_source, dtype=float).reshape((ENDPOINT_VELOCITY_CONSTRAINT_DIM,))
    x = np.asarray(x_gauss, dtype=float).copy()
    z0_jax = jnp.asarray(used_z0, dtype=jnp.float64)
    history_source_jax = jnp.asarray(used_history_source, dtype=jnp.float64)
    gamma_array = np.asarray(gamma, dtype=float)
    if gamma_array.ndim == 0:
        gamma_value = float(gamma_array)
        gamma_jax = jnp.asarray(gamma_value, dtype=jnp.float64)
        gamma_diag_value = gamma_value
    else:
        gamma_vector = gamma_array.reshape((ENDPOINT_VELOCITY_CONSTRAINT_DIM,))
        gamma_jax = jnp.asarray(gamma_vector, dtype=jnp.float64)
        gamma_diag_value = [float(value) for value in gamma_vector]
    args = build_args(state, h, params)
    total_residual = 0.0
    total_jac = 0.0
    total_linear = 0.0
    max_raw_linear_residual = 0.0
    max_scaled_linear_residual = 0.0
    max_raw_jacobian_condition = 0.0
    max_scaled_jacobian_condition = 0.0
    max_condition_reduction_raw_to_scaled = 0.0
    min_jacobian_rank = DIM
    final_norm = float("inf")
    newton_converged = False
    for it in range(80):
        x_jax = jnp.asarray(x, dtype=jnp.float64)
        started = time.perf_counter()
        res = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_TERMINAL_BLEND_VALUE(
                x_jax,
                z0_jax,
                history_source_jax,
                gamma_jax,
                *args,
            ),
            dtype=float,
        )
        total_residual += time.perf_counter() - started
        final_norm = float(np.linalg.norm(res))
        if final_norm < 1.0e-11:
            newton_converged = True
            break
        if not np.isfinite(final_norm) or final_norm > 1.0e8:
            raise RuntimeError(f"source-free recurrent terminal blend residual diverged: {final_norm:.3e}")
        started = time.perf_counter()
        jac = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_TERMINAL_BLEND_JAC(
                x_jax,
                z0_jax,
                history_source_jax,
                gamma_jax,
                *args,
            ),
            dtype=float,
        )
        total_jac += time.perf_counter() - started
        rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
        raw_condition = float(np.linalg.cond(jac))
        min_jacobian_rank = min(min_jacobian_rank, rank)
        max_raw_jacobian_condition = max(max_raw_jacobian_condition, raw_condition)
        started = time.perf_counter()
        delta, linear_diag = solve_newton_linear_system_np(jac, res, linear_solve_policy)
        total_linear += time.perf_counter() - started
        max_raw_linear_residual = max(max_raw_linear_residual, linear_diag["raw_linear_residual_norm"])
        max_scaled_linear_residual = max(max_scaled_linear_residual, linear_diag["scaled_linear_residual_norm"])
        max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, linear_diag["scaled_jacobian_condition"])
        max_condition_reduction_raw_to_scaled = max(
            max_condition_reduction_raw_to_scaled,
            linear_diag["condition_reduction_raw_to_scaled"],
        )
        x = x + delta
        if float(np.linalg.norm(delta)) < 1.0e-11:
            x_jax = jnp.asarray(x, dtype=jnp.float64)
            res = np.asarray(
                R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_TERMINAL_BLEND_VALUE(
                    x_jax,
                    z0_jax,
                    history_source_jax,
                    gamma_jax,
                    *args,
                ),
                dtype=float,
            )
            final_norm = float(np.linalg.norm(res))
            newton_converged = final_norm < 1.0e-10
            break

    x_jax = jnp.asarray(x, dtype=jnp.float64)
    started = time.perf_counter()
    candidate_res = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_TERMINAL_BLEND_VALUE(
            x_jax,
            z0_jax,
            history_source_jax,
            gamma_jax,
            *args,
        ),
        dtype=float,
    )
    total_residual += time.perf_counter() - started
    final_norm = float(np.linalg.norm(candidate_res))
    started = time.perf_counter()
    jac = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_RECURRENT_TERMINAL_BLEND_JAC(
            x_jax,
            z0_jax,
            history_source_jax,
            gamma_jax,
            *args,
        ),
        dtype=float,
    )
    total_jac += time.perf_counter() - started
    final_rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
    final_raw_condition = float(np.linalg.cond(jac))
    final_scaled_condition = scaled_condition_np(jac, "iterative")
    min_jacobian_rank = min(min_jacobian_rank, final_rank)
    max_raw_jacobian_condition = max(max_raw_jacobian_condition, final_raw_condition)
    max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, final_scaled_condition)
    max_condition_reduction_raw_to_scaled = max(
        max_condition_reduction_raw_to_scaled,
        final_raw_condition / max(final_scaled_condition, 1.0e-300),
    )
    newton_converged = bool(newton_converged or final_norm < 1.0e-10)

    stages = unpack_stages(x)
    terminal_z0 = paper_tfe_terminal_z_from_stages(stages)
    terminal_output_raw = paper_tfe_terminal_state_from_stages(state, stages, params=None, project_velocity=False)
    gauss_output_raw = next_state_from_stages(state, h, stages, params=None, project_velocity=False)
    raw_con, raw_vel = constraint_parts_np(terminal_output_raw, params, h)
    paper_kinematic_rows = paper_kinematic_substitution_stage_rows_np(candidate_res)
    paper_newton_euler_rows = stage_residual_block_np(candidate_res, "newton_euler_weak_balance")
    paper_lower_pair_rows = stage_residual_block_np(candidate_res, "lower_pair_index3_weak_constraints")
    source_consistency_rows = paper_lower_pair_rows[: (N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM]
    recurrent_terminal_blend_rows = paper_lower_pair_rows[(N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM :]
    next_history_source, history_diag = paper_tfe_lower_pair_stage0_source_history_np(x, h, args)
    return terminal_output_raw, terminal_z0, next_history_source, {
        "newton_iterations": it + 1,
        "newton_converged": newton_converged,
        "total_residual_eval_sec": total_residual,
        "total_jacobian_eval_sec": total_jac,
        "total_linear_solve_sec": total_linear,
        "residual_norm": final_norm,
        "max_paper_kinematic_row_norm": float(np.linalg.norm(paper_kinematic_rows)),
        "max_paper_newton_euler_row_norm": float(np.linalg.norm(paper_newton_euler_rows)),
        "max_source_free_lower_pair_row_norm": float(np.linalg.norm(paper_lower_pair_rows)),
        "max_source_consistency_row_norm": float(np.linalg.norm(source_consistency_rows)),
        "max_recurrent_terminal_blend_closure_row_norm": float(np.linalg.norm(recurrent_terminal_blend_rows)),
        "max_raw_terminal_endpoint_constraint_norm": float(np.linalg.norm(raw_con)),
        "max_raw_terminal_endpoint_velocity_constraint_norm": float(np.linalg.norm(raw_vel)),
        "max_terminal_vs_gauss_position_delta_norm": float(np.linalg.norm(terminal_output_raw.r - gauss_output_raw.r)),
        "max_terminal_vs_gauss_velocity_delta_norm": float(np.linalg.norm(terminal_output_raw.v - gauss_output_raw.v)),
        "min_jacobian_rank": min_jacobian_rank,
        "max_raw_jacobian_condition": max_raw_jacobian_condition,
        "max_scaled_jacobian_condition": max_scaled_jacobian_condition,
        "max_condition_reduction_raw_to_scaled": max_condition_reduction_raw_to_scaled,
        "max_raw_linear_residual_norm": max_raw_linear_residual,
        "max_scaled_linear_residual_norm": max_scaled_linear_residual,
        "max_terminal_z0_update_delta_norm": float(np.linalg.norm(terminal_z0 - used_z0)),
        "max_terminal_z0_norm": float(np.linalg.norm(terminal_z0)),
        "history_source_norm": float(np.linalg.norm(used_history_source)),
        "next_history_source_norm": float(np.linalg.norm(next_history_source)),
        "history_source_update_norm": float(np.linalg.norm(next_history_source - used_history_source)),
        "stage0_source_norm": history_diag["stage0_source_norm"],
        "mean_source_norm": history_diag["mean_source_norm"],
        "source_curvature_norm": history_diag["source_curvature_norm"],
        "history_source_bootstrap_policy": "zero_initial_then_stage0_source_estimate",
        "gamma": gamma_diag_value,
        "raw_terminal_endpoint_velocity_constraint_vector": [float(value) for value in raw_vel],
        "linear_solve_policy": linear_solve_policy,
    }


def endpoint_tfe_paper_lower_pair_source_free_endpoint_pose_velocity_predictor_step(
    state: State,
    params: Params,
    previous_terminal_z0: np.ndarray,
    history_source: np.ndarray,
    predictor_law: str,
    h: float = H,
    linear_solve_policy: str = "iterative_equilibrated",
):
    x_gauss, _ = solve_gauss_stage_x(state, params, h)
    used_z0 = np.asarray(previous_terminal_z0, dtype=float)
    used_history_source = np.asarray(history_source, dtype=float).reshape((-1,))
    if used_history_source.size not in (
        ENDPOINT_VELOCITY_CONSTRAINT_DIM,
        2 * ENDPOINT_VELOCITY_CONSTRAINT_DIM,
        3 * ENDPOINT_VELOCITY_CONSTRAINT_DIM,
        4 * ENDPOINT_VELOCITY_CONSTRAINT_DIM,
    ):
        raise ValueError(
            "endpoint pose velocity predictor history_source must contain one, two, three, or four "
            f"{ENDPOINT_VELOCITY_CONSTRAINT_DIM}-entry source blocks; got {used_history_source.size}"
        )
    x = np.asarray(x_gauss, dtype=float).copy()
    z0_jax = jnp.asarray(used_z0, dtype=jnp.float64)
    history_source_jax = jnp.asarray(used_history_source, dtype=jnp.float64)
    args = build_args(state, h, params)
    total_residual = 0.0
    total_jac = 0.0
    total_linear = 0.0
    max_raw_linear_residual = 0.0
    max_scaled_linear_residual = 0.0
    max_raw_jacobian_condition = 0.0
    max_scaled_jacobian_condition = 0.0
    max_condition_reduction_raw_to_scaled = 0.0
    min_jacobian_rank = DIM
    final_norm = float("inf")
    newton_converged = False
    for it in range(80):
        x_jax = jnp.asarray(x, dtype=jnp.float64)
        started = time.perf_counter()
        res = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ENDPOINT_POSE_VELOCITY_PREDICTOR_VALUE(
                x_jax,
                z0_jax,
                history_source_jax,
                predictor_law,
                *args,
            ),
            dtype=float,
        )
        total_residual += time.perf_counter() - started
        final_norm = float(np.linalg.norm(res))
        if final_norm < 1.0e-11:
            newton_converged = True
            break
        if not np.isfinite(final_norm) or final_norm > 1.0e8:
            raise RuntimeError(
                f"endpoint-pose velocity predictor residual diverged for {predictor_law}: {final_norm:.3e}"
            )
        started = time.perf_counter()
        jac = np.asarray(
            R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ENDPOINT_POSE_VELOCITY_PREDICTOR_JAC(
                x_jax,
                z0_jax,
                history_source_jax,
                predictor_law,
                *args,
            ),
            dtype=float,
        )
        total_jac += time.perf_counter() - started
        rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
        raw_condition = float(np.linalg.cond(jac))
        min_jacobian_rank = min(min_jacobian_rank, rank)
        max_raw_jacobian_condition = max(max_raw_jacobian_condition, raw_condition)
        started = time.perf_counter()
        delta, linear_diag = solve_newton_linear_system_np(jac, res, linear_solve_policy)
        total_linear += time.perf_counter() - started
        max_raw_linear_residual = max(max_raw_linear_residual, linear_diag["raw_linear_residual_norm"])
        max_scaled_linear_residual = max(max_scaled_linear_residual, linear_diag["scaled_linear_residual_norm"])
        max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, linear_diag["scaled_jacobian_condition"])
        max_condition_reduction_raw_to_scaled = max(
            max_condition_reduction_raw_to_scaled,
            linear_diag["condition_reduction_raw_to_scaled"],
        )
        x = x + delta
        if float(np.linalg.norm(delta)) < 1.0e-11:
            x_jax = jnp.asarray(x, dtype=jnp.float64)
            res = np.asarray(
                R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ENDPOINT_POSE_VELOCITY_PREDICTOR_VALUE(
                    x_jax,
                    z0_jax,
                    history_source_jax,
                    predictor_law,
                    *args,
                ),
                dtype=float,
            )
            final_norm = float(np.linalg.norm(res))
            newton_converged = final_norm < 1.0e-10
            break

    x_jax = jnp.asarray(x, dtype=jnp.float64)
    started = time.perf_counter()
    candidate_res = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ENDPOINT_POSE_VELOCITY_PREDICTOR_VALUE(
            x_jax,
            z0_jax,
            history_source_jax,
            predictor_law,
            *args,
        ),
        dtype=float,
    )
    total_residual += time.perf_counter() - started
    final_norm = float(np.linalg.norm(candidate_res))
    started = time.perf_counter()
    jac = np.asarray(
        R_ENDPOINT_TFE_PAPER_LOWER_PAIR_SOURCE_FREE_ENDPOINT_POSE_VELOCITY_PREDICTOR_JAC(
            x_jax,
            z0_jax,
            history_source_jax,
            predictor_law,
            *args,
        ),
        dtype=float,
    )
    total_jac += time.perf_counter() - started
    final_rank = int(np.linalg.matrix_rank(jac, tol=1.0e-10))
    final_raw_condition = float(np.linalg.cond(jac))
    final_scaled_condition = scaled_condition_np(jac, "iterative")
    min_jacobian_rank = min(min_jacobian_rank, final_rank)
    max_raw_jacobian_condition = max(max_raw_jacobian_condition, final_raw_condition)
    max_scaled_jacobian_condition = max(max_scaled_jacobian_condition, final_scaled_condition)
    max_condition_reduction_raw_to_scaled = max(
        max_condition_reduction_raw_to_scaled,
        final_raw_condition / max(final_scaled_condition, 1.0e-300),
    )
    newton_converged = bool(newton_converged or final_norm < 1.0e-10)

    stages = unpack_stages(x)
    terminal_z0 = paper_tfe_terminal_z_from_stages(stages)
    terminal_output_raw = paper_tfe_terminal_state_from_stages(state, stages, params=None, project_velocity=False)
    gauss_output_raw = next_state_from_stages(state, h, stages, params=None, project_velocity=False)
    raw_con, raw_vel = constraint_parts_np(terminal_output_raw, params, h)
    paper_kinematic_rows = paper_kinematic_substitution_stage_rows_np(candidate_res)
    paper_newton_euler_rows = stage_residual_block_np(candidate_res, "newton_euler_weak_balance")
    paper_lower_pair_rows = stage_residual_block_np(candidate_res, "lower_pair_index3_weak_constraints")
    source_consistency_rows = paper_lower_pair_rows[: (N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM]
    predictor_rows = paper_lower_pair_rows[(N_STAGES - 1) * ENDPOINT_VELOCITY_CONSTRAINT_DIM :]
    next_history_source, history_diag = paper_tfe_lower_pair_stage0_source_history_np(x, h, args)
    if used_history_source.size >= 4 * ENDPOINT_VELOCITY_CONSTRAINT_DIM:
        next_history_state = np.concatenate(
            [
                next_history_source,
                used_history_source[: 3 * ENDPOINT_VELOCITY_CONSTRAINT_DIM],
            ]
        )
    elif used_history_source.size >= 3 * ENDPOINT_VELOCITY_CONSTRAINT_DIM:
        next_history_state = np.concatenate(
            [
                next_history_source,
                used_history_source[: 2 * ENDPOINT_VELOCITY_CONSTRAINT_DIM],
            ]
        )
    elif used_history_source.size >= 2 * ENDPOINT_VELOCITY_CONSTRAINT_DIM:
        next_history_state = np.concatenate(
            [
                next_history_source,
                used_history_source[:ENDPOINT_VELOCITY_CONSTRAINT_DIM],
            ]
        )
    else:
        next_history_state = next_history_source
    return terminal_output_raw, terminal_z0, next_history_state, {
        "newton_iterations": it + 1,
        "newton_converged": newton_converged,
        "total_residual_eval_sec": total_residual,
        "total_jacobian_eval_sec": total_jac,
        "total_linear_solve_sec": total_linear,
        "residual_norm": final_norm,
        "max_paper_kinematic_row_norm": float(np.linalg.norm(paper_kinematic_rows)),
        "max_paper_newton_euler_row_norm": float(np.linalg.norm(paper_newton_euler_rows)),
        "max_source_free_lower_pair_row_norm": float(np.linalg.norm(paper_lower_pair_rows)),
        "max_source_consistency_row_norm": float(np.linalg.norm(source_consistency_rows)),
        "max_endpoint_pose_velocity_predictor_closure_row_norm": float(np.linalg.norm(predictor_rows)),
        "max_raw_terminal_endpoint_constraint_norm": float(np.linalg.norm(raw_con)),
        "max_raw_terminal_endpoint_velocity_constraint_norm": float(np.linalg.norm(raw_vel)),
        "max_terminal_vs_gauss_position_delta_norm": float(np.linalg.norm(terminal_output_raw.r - gauss_output_raw.r)),
        "max_terminal_vs_gauss_velocity_delta_norm": float(np.linalg.norm(terminal_output_raw.v - gauss_output_raw.v)),
        "min_jacobian_rank": min_jacobian_rank,
        "max_raw_jacobian_condition": max_raw_jacobian_condition,
        "max_scaled_jacobian_condition": max_scaled_jacobian_condition,
        "max_condition_reduction_raw_to_scaled": max_condition_reduction_raw_to_scaled,
        "max_raw_linear_residual_norm": max_raw_linear_residual,
        "max_scaled_linear_residual_norm": max_scaled_linear_residual,
        "max_terminal_z0_update_delta_norm": float(np.linalg.norm(terminal_z0 - used_z0)),
        "max_terminal_z0_norm": float(np.linalg.norm(terminal_z0)),
        "history_source_norm": float(np.linalg.norm(used_history_source)),
        "next_history_source_norm": float(np.linalg.norm(next_history_state)),
        "history_source_update_norm": float(np.linalg.norm(next_history_state - used_history_source)),
        "stage0_source_norm": history_diag["stage0_source_norm"],
        "mean_source_norm": history_diag["mean_source_norm"],
        "source_curvature_norm": history_diag["source_curvature_norm"],
        "history_source_bootstrap_policy": (
            "four_zero_initial_blocks_then_stage0_source_estimate_shift_register"
            if used_history_source.size >= 4 * ENDPOINT_VELOCITY_CONSTRAINT_DIM
            else (
                "three_zero_initial_blocks_then_stage0_source_estimate_shift_register"
                if used_history_source.size >= 3 * ENDPOINT_VELOCITY_CONSTRAINT_DIM
                else (
                    "two_zero_initial_blocks_then_stage0_source_estimate_shift_register"
                    if used_history_source.size >= 2 * ENDPOINT_VELOCITY_CONSTRAINT_DIM
                    else "zero_initial_then_stage0_source_estimate"
                )
            )
        ),
        "predictor_law": predictor_law,
        "linear_solve_policy": linear_solve_policy,
    }


def integrate_endpoint_tfe_paper_lower_pair_source_free_order_closure_blend(
    params: Params,
    beta: float,
    h: float = H,
    t_final: float = T_FINAL,
):
    linear_solve_policy = "iterative_equilibrated"
    state = project_endpoint_velocity(initial_state(params), params)
    terminal_z0, initial_diag = paper_tfe_start_z0_consistent_initial_acceleration_np(state, params, h)
    totals = {
        "total_newton_iterations": initial_diag["newton_iterations"],
        "max_newton_iterations": initial_diag["newton_iterations"],
        "total_residual_eval_sec": initial_diag["total_residual_eval_sec"],
        "total_jacobian_eval_sec": initial_diag["total_jacobian_eval_sec"],
        "total_linear_solve_sec": initial_diag["total_linear_solve_sec"],
        "max_residual_norm": 0.0,
        "max_source_consistency_row_norm": 0.0,
        "max_order_closure_blend_closure_row_norm": 0.0,
        "max_source_free_lower_pair_row_norm": 0.0,
        "max_paper_kinematic_row_norm": 0.0,
        "max_paper_newton_euler_row_norm": 0.0,
        "max_raw_terminal_endpoint_constraint_norm": 0.0,
        "max_raw_terminal_endpoint_velocity_constraint_norm": 0.0,
        "max_terminal_vs_gauss_position_delta_norm": 0.0,
        "max_terminal_vs_gauss_velocity_delta_norm": 0.0,
        "min_jacobian_rank": DIM,
        "max_raw_jacobian_condition": 0.0,
        "max_scaled_jacobian_condition": 0.0,
        "max_condition_reduction_raw_to_scaled": 0.0,
        "max_raw_linear_residual_norm": initial_diag["initial_z0_linear_residual_norm"],
        "max_scaled_linear_residual_norm": initial_diag["initial_z0_linear_residual_norm"],
        "initial_z0_residual_norm": initial_diag["initial_z0_residual_norm"],
        "initial_z0_jacobian_rank": initial_diag["initial_z0_jacobian_rank"],
        "initial_z0_jacobian_condition": initial_diag["initial_z0_jacobian_condition"],
        "initial_z0_norm": initial_diag["initial_z0_norm"],
        "max_terminal_z0_update_delta_norm": 0.0,
        "max_terminal_z0_norm": float(np.linalg.norm(terminal_z0)),
        "source_free_converged_step_count": 0,
        "linear_solve_policy": linear_solve_policy,
    }
    n_steps = int(round(t_final / h))
    for _ in range(n_steps):
        state, terminal_z0, diag = endpoint_tfe_paper_lower_pair_source_free_order_closure_blend_step(
            state,
            params,
            terminal_z0,
            beta,
            h=h,
            linear_solve_policy=linear_solve_policy,
        )
        totals["total_newton_iterations"] += diag["newton_iterations"]
        totals["max_newton_iterations"] = max(totals["max_newton_iterations"], diag["newton_iterations"])
        totals["min_jacobian_rank"] = min(totals["min_jacobian_rank"], diag["min_jacobian_rank"])
        if diag["newton_converged"]:
            totals["source_free_converged_step_count"] += 1
        for key in [
            "total_residual_eval_sec",
            "total_jacobian_eval_sec",
            "total_linear_solve_sec",
        ]:
            totals[key] += diag[key]
        for key in [
            "residual_norm",
            "max_source_consistency_row_norm",
            "max_order_closure_blend_closure_row_norm",
            "max_source_free_lower_pair_row_norm",
            "max_paper_kinematic_row_norm",
            "max_paper_newton_euler_row_norm",
            "max_raw_terminal_endpoint_constraint_norm",
            "max_raw_terminal_endpoint_velocity_constraint_norm",
            "max_terminal_vs_gauss_position_delta_norm",
            "max_terminal_vs_gauss_velocity_delta_norm",
            "max_raw_jacobian_condition",
            "max_scaled_jacobian_condition",
            "max_condition_reduction_raw_to_scaled",
            "max_raw_linear_residual_norm",
            "max_scaled_linear_residual_norm",
            "max_terminal_z0_update_delta_norm",
            "max_terminal_z0_norm",
        ]:
            total_key = "max_residual_norm" if key == "residual_norm" else key
            value = float(diag[key])
            if np.isfinite(value):
                totals[total_key] = max(totals[total_key], value)
    totals["state"] = state
    totals["steps"] = n_steps
    return totals


