    for it in range(80):
        y_jax = jnp.asarray(y, dtype=jnp.float64)
        started = time.perf_counter()
        res = np.asarray(R_ENDPOINT_TFE_STAGE_PROBE_BLOCK_ACTIVATION_VALUE(y_jax, component_mask, *args), dtype=float)
        total_residual += time.perf_counter() - started
