    h005 = next((item for item in summaries if abs(item["h"] - 0.005) < 1.0e-15), summaries[-2])
    for item in summaries:
        position_reduction = h005["position_error"] / max(item["position_error"], 1.0e-300)
        velocity_reduction = h005["velocity_error"] / max(item["velocity_error"], 1.0e-300)
        runtime_factor = item["runtime_sec"] / max(h005["runtime_sec"], 1.0e-300)
