        fit_norm, fit_relative = fit_residual_for_sample(matrix, sample)
        value_residual = closure_value - sample["target_value"]
        value_residual_norm = float(np.linalg.norm(value_residual))
        target_value_norm = max(float(np.linalg.norm(sample["target_value"])), 1.0e-300)
        value_relative_residual = value_residual_norm / target_value_norm
        spans = bool(
            metrics["independent_target_rank"] == 0
            and metrics["projection_relative_residual"] < rel_tol
            and metrics["max_row_relative_residual"] < rel_tol
        )
