    def analytic_saturation_fractions(
        law_name: str,
        gradient_cap: float,
        required_gradient_norm: float,
        required_row_gradients: np.ndarray,
    ) -> np.ndarray:
        def tanh_fraction(x: np.ndarray) -> np.ndarray:
            x_abs = np.abs(x)
            return np.where(
                x_abs < 1.0e-8,
                1.0 - x_abs * x_abs / 3.0,
                np.tanh(x_abs) / np.maximum(x_abs, 1.0e-300),
            )

        cap = max(float(gradient_cap), 1.0e-300)
        if law_name == "global_tanh_saturation":
            ratio = np.asarray([required_gradient_norm / cap], dtype=float)
            return np.full(required_row_gradients.shape, float(tanh_fraction(ratio)[0]), dtype=float)
        if law_name == "rowwise_tanh_saturation":
            return tanh_fraction(required_row_gradients / cap)
        if law_name == "rowwise_rational_quadratic_saturation":
            ratios = required_row_gradients / cap
            return 1.0 / np.sqrt(1.0 + ratios * ratios)
        raise ValueError(f"unknown analytic saturation law: {law_name}")

    def emit_bounded_formula_value_level_row(
        sample: dict,
        candidate_name: str,
        candidate_kind: str,
        matrix: np.ndarray,
        fit_scope: str,
        active_velocity_indices: list[int],
        training_sample_count: int,
        law_name: str,
        gradient_cap: float,
    ) -> dict:
        closure_jac = matrix @ sample["velocity_jac"]
        closure_value = matrix @ sample["velocity_value"]
        base_basis_jac = np.vstack([sample["source_jac"], closure_jac])
        base_metrics = projection_metrics(base_basis_jac, sample["target_jac"])
        closure_perp = matrix @ sample["velocity_perp"]
