    def weak_row_structure_capacity_parts(
        sample: dict,
        active_velocity_indices: list[int],
    ) -> dict:
        cache = sample.setdefault("_weak_row_structure_capacity_cache", {})
        active_key = tuple(active_velocity_indices)
        if active_key in cache:
            return cache[active_key]
        rows_source_raw = np.asarray(sample["source_jac"], dtype=float)
        rows_source = normalize_feature_rows(rows_source_raw)
        rows_active = normalize_feature_rows(
            np.asarray(sample["velocity_perp"], dtype=float)[active_velocity_indices, :]
        )
        if rows_active.size == 0:
            zero = np.zeros((0, DIM), dtype=float)
            result = {
                "rows_active": zero,
                "active_cross_gram_perp": zero,
                "source_active_hadamard_perp": zero,
                "source_active_cross_hadamard_perp": zero,
                "source_active_shifted_commutator_perp": zero,
                "active_direction_count": 0,
                "source_direction_count": rows_source.shape[0],
                "cross_gram_direction_count": 0,
                "hadamard_direction_count": 0,
                "commutator_direction_count": 0,
            }
            cache[active_key] = result
            return result
        cross_gram = rows_source @ rows_active.T
        active_cross_gram = residualize_against_source(cross_gram @ rows_active, rows_source_raw)
        hadamard_raw = (rows_source[:, None, :] * rows_active[None, :, :]).reshape((-1, DIM))
        source_active_hadamard = residualize_against_source(hadamard_raw, rows_source_raw)
        cross_hadamard_raw = (cross_gram[:, :, None] * rows_source[:, None, :] * rows_active[None, :, :]).reshape(
            (-1, DIM)
        )
        source_active_cross_hadamard = residualize_against_source(cross_hadamard_raw, rows_source_raw)
        shifted_source = np.roll(rows_source, 1, axis=1)
        shifted_active = np.roll(rows_active, 1, axis=1)
        shifted_commutator_raw = (
            rows_source[:, None, :] * shifted_active[None, :, :]
            - shifted_source[:, None, :] * rows_active[None, :, :]
        ).reshape((-1, DIM))
        source_active_shifted_commutator = residualize_against_source(
            shifted_commutator_raw,
            rows_source_raw,
        )
        result = {
            "rows_active": rows_active,
            "active_cross_gram_perp": active_cross_gram,
            "source_active_hadamard_perp": source_active_hadamard,
            "source_active_cross_hadamard_perp": source_active_cross_hadamard,
            "source_active_shifted_commutator_perp": source_active_shifted_commutator,
            "active_direction_count": rows_active.shape[0],
            "source_direction_count": rows_source.shape[0],
            "cross_gram_direction_count": active_cross_gram.shape[0],
            "hadamard_direction_count": source_active_hadamard.shape[0],
            "commutator_direction_count": source_active_shifted_commutator.shape[0],
        }
        cache[active_key] = result
        return result

    def weak_row_structure_capacity_feature_rows(
        sample: dict,
        active_velocity_indices: list[int],
        feature_family: str,
    ) -> tuple[np.ndarray, str, int, bool, bool, bool, bool, bool, bool]:
        parts = weak_row_structure_capacity_parts(sample, active_velocity_indices)
        rows_active = parts["rows_active"]
        active_cross_gram = parts["active_cross_gram_perp"]
        source_active_hadamard = parts["source_active_hadamard_perp"]
        source_active_cross_hadamard = parts["source_active_cross_hadamard_perp"]
        source_active_shifted_commutator = parts["source_active_shifted_commutator_perp"]
        active_count = int(parts["active_direction_count"])
        cross_count = int(parts["cross_gram_direction_count"])
        hadamard_count = int(parts["hadamard_direction_count"])
        commutator_count = int(parts["commutator_direction_count"])
        if feature_family == "weak_active_cross_gram_rows_perp":
            result = (
                active_cross_gram,
                "source/active cross-Gram weighted non-final velocity rows residualized against source rows",
                cross_count,
                True,
                True,
                True,
                False,
                False,
                False,
            )
        elif feature_family == "weak_source_active_hadamard_rows_perp":
            result = (
                source_active_hadamard,
                "pairwise source-row and non-final velocity-row Hadamard products residualized against source rows",
                hadamard_count,
                True,
                True,
                False,
                True,
                False,
                False,
            )
        elif feature_family == "active_plus_weak_source_active_hadamard_rows_perp":
            result = (
                np.vstack([rows_active, source_active_hadamard]),
                "active non-final velocity plus source/active Hadamard weak-row structure rows",
                active_count + hadamard_count,
                True,
                True,
                False,
                True,
                False,
                False,
            )
        elif feature_family == "weak_source_active_cross_hadamard_rows_perp":
            result = (
                source_active_cross_hadamard,
                "cross-Gram weighted source/active Hadamard weak-row structure rows",
                hadamard_count,
                True,
                True,
                True,
                True,
                False,
                False,
            )
        elif feature_family == "weak_source_active_shifted_commutator_rows_perp":
            result = (
                source_active_shifted_commutator,
                "shifted source/active commutator-like weak-row structure products",
                commutator_count,
                True,
                True,
                False,
                False,
                True,
                False,
            )
        elif feature_family == "active_plus_weak_source_active_shifted_commutator_rows_perp":
            result = (
                np.vstack([rows_active, source_active_shifted_commutator]),
                "active non-final velocity plus shifted source/active commutator-like weak-row structure products",
                active_count + commutator_count,
                True,
                True,
                False,
                False,
                True,
                False,
            )
        else:
            raise ValueError(f"unknown weak-row structure capacity feature family: {feature_family}")
        return result

    def emit_history_capacity_row(
        sample: dict,
        candidate_name: str,
        candidate_kind: str,
        matrix: np.ndarray,
        fit_scope: str,
        active_velocity_indices: list[int],
        training_sample_count: int,
        feature_family: str,
    ) -> dict:
        closure_jac = matrix @ sample["velocity_jac"]
        closure_value = matrix @ sample["velocity_value"]
        closure_perp = matrix @ sample["velocity_perp"]
        derivative_correction = sample["target_perp"] - closure_perp
        (
            feature_rows,
            feature_scope,
            direction_count,
            source_transport,
            velocity_transport,
            combined_transport,
            uses_final_stage,
        ) = history_capacity_feature_rows(sample, active_velocity_indices, feature_family)
        projected_correction = project_rows_onto_feature_space(derivative_correction, feature_rows)
        history_closure_jac = closure_jac + projected_correction
        basis_jac = np.vstack([sample["source_jac"], history_closure_jac])
        metrics = projection_metrics(basis_jac, sample["target_jac"])
        feature = feature_space_metrics(feature_rows)
        residual = derivative_correction - projected_correction
        row_target_norms = np.linalg.norm(derivative_correction, axis=1)
        row_residual_norms = np.linalg.norm(residual, axis=1)
        row_relative = row_residual_norms / np.maximum(row_target_norms, 1.0e-300)
        correction_norm = float(np.linalg.norm(derivative_correction))
        correction_residual_norm = float(np.linalg.norm(residual))
        value_residual_norm = float(np.linalg.norm(closure_value - sample["target_value"]))
        value_ok = bool(value_residual_norm < value_tol)
        selector = selector_degeneracy_metrics(matrix)
        meaningful_nonfinal = bool(selector["nonfinal_fraction"] >= meaningful_nonfinal_threshold)
        spans = bool(
            metrics["independent_target_rank"] == 0
            and metrics["projection_relative_residual"] < rel_tol
            and metrics["max_row_relative_residual"] < rel_tol
        )
        active_stages = active_stage_rows_from_indices(active_velocity_indices)
        return {
            "case": sample["case"],
            "h": f"{sample['h']:.10g}",
            "candidate_basis": candidate_name,
            "status": status_history_capacity_spans if spans and value_ok and meaningful_nonfinal else status_history_capacity_gap,
            "error_message": "",
            "candidate_kind": candidate_kind,
            "fit_scope": fit_scope,
            "feature_family": feature_family,
            "feature_scope": feature_scope,
            "active_stage_rows": ",".join(str(stage) for stage in active_stages),
            "training_sample_count": training_sample_count,
            "basis_row_count": basis_jac.shape[0],
            "compression_row_count": history_closure_jac.shape[0],
            "source_consistency_rows": split,
            "velocity_stage_rows": sample["velocity_jac"].shape[0],
            "active_velocity_rows": len(active_velocity_indices),
            "history_feature_rows": feature_rows.shape[0],
            "history_feature_rank": feature["rank"],
            "history_feature_condition": f"{feature['condition']:.16e}",
            "history_step_count": 1,
            "history_direction_count": direction_count,
            "history_delta_norm": f"{float(np.linalg.norm(feature_rows)):.16e}",
            "history_source_transport_used": str(bool(source_transport)),
            "history_velocity_transport_used": str(bool(velocity_transport)),
            "history_combined_transport_used": str(bool(combined_transport)),
            "uses_final_stage_velocity_feature": str(bool(uses_final_stage)),
            "target_row_count": sample["target_jac"].shape[0],
            "stage_unknown_count": basis_jac.shape[1],
            "basis_rank": metrics["basis_rank"],
            "augmented_rank": metrics["augmented_rank"],
            "independent_target_rank": metrics["independent_target_rank"],
            "basis_condition": f"{metrics['basis_condition']:.16e}",
            "target_jacobian_norm": f"{metrics['target_jacobian_norm']:.16e}",
            "oracle_correction_norm": f"{correction_norm:.16e}",
            "history_projected_correction_norm": f"{float(np.linalg.norm(projected_correction)):.16e}",
            "history_correction_residual_norm": f"{correction_residual_norm:.16e}",
            "history_correction_relative_residual": f"{correction_residual_norm / max(correction_norm, 1.0e-300):.16e}",
            "max_history_row_relative_residual": f"{float(np.max(row_relative)):.16e}",
            "projection_residual_norm": f"{metrics['projection_residual_norm']:.16e}",
            "projection_relative_residual": f"{metrics['projection_relative_residual']:.16e}",
            "max_row_relative_residual": f"{metrics['max_row_relative_residual']:.16e}",
            "min_row_relative_residual": f"{metrics['min_row_relative_residual']:.16e}",
            "value_residual_norm": f"{value_residual_norm:.16e}",
            "value_level_balance_ok": str(value_ok),
            "meaningful_nonfinal_energy": str(meaningful_nonfinal),
            "target_jacobian_used_for_capacity_fit": "True",
            "target_direction_oracle_used_for_formula": "False",
            "endpoint_boundary_source_removed": "True",
            "target_terminal_boundary_row_used": "True",
            "terminal_row_replacement_used": "False",
            "projection_used": "False",
            "accepted_h_sweep_present": "False",
            "full_tfe_stage_replacement": "False",
            "history_capacity_spans_target": str(spans),
            "blocking_gap": (
                "One-step history-transport feature capacity can reproduce the local correction, but "
                "the coefficients are still target-Jacobian fitted and not an implemented history law or h-sweep."
                if spans and value_ok and meaningful_nonfinal
                else "The tested one-step history-transport non-final source features do not reproduce the local correction."
            ),
            "next_repair_target": (
                "derive target-free weights for the one-step history transport features and rerun the nonlinear h-sweep"
                if spans
                else "derive a revised weak-row formula or multi-step nonlinear history source law for the coefficient-gradient closure"
            ),
            "notes": (
                "This capacity audit builds a one-step transported local state from the current terminal output "
                "and tests source-row/velocity-row deltas as history features. It is a trajectory-history "
                "feature-space test, not a target-free formula and not an accepted nonlinear h-sweep."
            ),
        }

