def plot_sharp_refinement_cost_envelope_audit(cost_envelope: dict) -> None:
    import matplotlib.pyplot as plt

    rows = cost_envelope.get("runs", [])
    if not rows:
        return
    labels = [row["regime"].replace("_", "\n") for row in rows]
    x = np.arange(len(rows))
    position_all = np.asarray([float(row["position_observed_order_all"]) for row in rows], dtype=float)
    velocity_all = np.asarray([float(row["velocity_observed_order_all"]) for row in rows], dtype=float)
    position_tail = np.asarray([float(row["position_tail_order"]) for row in rows], dtype=float)
    velocity_tail = np.asarray([float(row["velocity_tail_order"]) for row in rows], dtype=float)
    runtime_factor = np.asarray([float(row["runtime_factor_vs_h001"]) for row in rows], dtype=float)
    step_factor = np.asarray([float(row["accepted_steps_factor_vs_h001"]) for row in rows], dtype=float)
    newton_factor = np.asarray([float(row["newton_iteration_factor_vs_h001"]) for row in rows], dtype=float)
    velocity_reduction = np.asarray([float(row["velocity_error_reduction_vs_h001"]) for row in rows], dtype=float)

    fig, axes = plt.subplots(1, 3, figsize=(13.6, 4.2))
    width = 0.18
    axes[0].bar(x - 1.5 * width, position_all, width, label="pos all")
    axes[0].bar(x - 0.5 * width, velocity_all, width, label="vel all")
    axes[0].bar(x + 0.5 * width, position_tail, width, label="pos tail")
    axes[0].bar(x + 1.5 * width, velocity_tail, width, label="vel tail")
    axes[0].axhline(5.5, color="0.2", lw=1.0, ls="--", label="high-order target")
    axes[0].set_ylabel("observed order")
    axes[0].set_title("sharp refinement order windows")

    axes[1].bar(x - width, runtime_factor, width, label="runtime")
    axes[1].bar(x, step_factor, width, label="steps")
    axes[1].bar(x + width, newton_factor, width, label="Newton iters")
    axes[1].set_yscale("log")
    axes[1].set_ylabel("factor vs h=0.01")
    axes[1].set_title("work to enter each window")

    axes[2].bar(x, np.maximum(velocity_reduction, 1.0e-300), 0.42, label="velocity error reduction")
    axes[2].set_yscale("log")
    axes[2].set_ylabel("reduction vs h=0.01")
    axes[2].set_title("accuracy gained")

    for ax in axes:
        ax.set_xticks(x)
        ax.set_xticklabels(labels, fontsize=8)
        ax.grid(True, which="both", axis="y", alpha=0.35)
        ax.legend(fontsize=8)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_sharp_refinement_cost_envelope_audit.png", dpi=180)
    plt.close(fig)


