def plot_endpoint_kkt_closure(closure: dict) -> None:
    import matplotlib.pyplot as plt

    fig, axes = plt.subplots(1, 2, figsize=(10.4, 4.0))
    for case_name, case in closure["cases"].items():
        label = case_name.replace("cylindrical_", "")
        h_values = np.asarray(case["h_values"], dtype=float)
        axes[0].loglog(h_values, case["position_errors"], "o-", label=f"{label} pos")
        axes[0].loglog(h_values, case["velocity_errors"], "s--", label=f"{label} vel")
        axes[1].loglog(h_values, np.maximum(case["endpoint_corrections"], 1.0e-300), "o-", label=f"{label} correction")
    axes[0].set_ylabel("error vs endpoint-KKT h=0.005")
    axes[1].set_ylabel("endpoint KKT correction norm")
    for ax in axes:
        ax.set_xlabel("h")
        ax.grid(True, which="both", alpha=0.35)
        ax.invert_xaxis()
        ax.legend(fontsize=8)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_kkt_closure.png", dpi=180)
    plt.close(fig)


def plot_endpoint_tfe_gap_audit(gap: dict) -> None:
    import matplotlib.pyplot as plt

    fig, axes = plt.subplots(1, 2, figsize=(10.8, 4.1))
    for case_name, case in gap.get("cases", {}).items():
        label = case_name.replace("cylindrical_", "")
        rows = case.get("rows", [])
        h_values = np.asarray([row["h"] for row in rows], dtype=float)
        projection_delta = np.asarray([row["projection_delta_norm"] for row in rows], dtype=float)
        kkt_correction = np.asarray([row["kkt_endpoint_correction_norm"] for row in rows], dtype=float)
        closure_gain = np.asarray([row["kkt_closure_gain_raw_over_closed"] for row in rows], dtype=float)
        ratio = np.asarray([row["kkt_over_projection_correction_ratio"] for row in rows], dtype=float)
        axes[0].loglog(h_values, np.maximum(projection_delta, 1.0e-300), "o-", label=f"{label} projection delta")
        axes[0].loglog(h_values, np.maximum(kkt_correction, 1.0e-300), "s--", label=f"{label} KKT correction")
        axes[1].loglog(h_values, np.maximum(closure_gain, 1.0e-300), "o-", label=f"{label} raw/closed")
        axes[1].loglog(h_values, np.maximum(ratio, 1.0e-300), "s--", label=f"{label} KKT/proj correction")
    axes[0].set_ylabel("endpoint velocity correction norm")
    axes[1].set_ylabel("closure gain or correction ratio")
    for ax in axes:
        ax.set_xlabel("h")
        ax.grid(True, which="both", alpha=0.35)
        ax.invert_xaxis()
        ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_gap_audit.png", dpi=180)
    plt.close(fig)


