def plot_endpoint_tfe_stage_replacement_design_audit(design: dict) -> None:
    import matplotlib.pyplot as plt

    rows = design.get("rows", [])
    if not rows:
        return
    statuses = ["satisfied", "partial", "missing"]
    counts = design.get("counts", {})
    stage_related = [row for row in rows if int(row["proposed_rows"]) > 0 or int(row["current_rows"]) > 0]
    labels = [row["requirement"].replace("_", "\n") for row in stage_related]
    current_rows = np.asarray([int(row["current_rows"]) for row in stage_related], dtype=float)
    proposed_rows = np.asarray([int(row["proposed_rows"]) for row in stage_related], dtype=float)
    xs = np.arange(len(labels))
    fig, axes = plt.subplots(1, 2, figsize=(11.8, 4.2))
    axes[0].bar(statuses, [counts.get(status, 0) for status in statuses], color=["#2f7d32", "#a86f00", "#b3261e"])
    axes[0].set_ylabel("design check count")
    axes[0].set_title("full TFE stage replacement design status")
    axes[1].bar(xs - 0.18, current_rows, width=0.36, label="current rows", color="#4c6f91")
    axes[1].bar(xs + 0.18, proposed_rows, width=0.36, label="proposed rows", color="#7c6a2f")
    axes[1].set_ylabel("row count")
    axes[1].set_xticks(xs)
    axes[1].set_xticklabels(labels, rotation=40, ha="right", fontsize=7)
    axes[1].legend(fontsize=8)
    for ax in axes:
        ax.grid(True, axis="y", alpha=0.35)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_stage_replacement_design_audit.png", dpi=180)
    plt.close(fig)


def plot_endpoint_tfe_stage_functional_spec_audit(spec: dict) -> None:
    import matplotlib.pyplot as plt

    rows = spec.get("rows", [])
    budget_rows = [row for row in rows if row.get("counts_toward_stage_budget") == "True"]
    if not budget_rows:
        return
    labels = [row["block"].replace("_", "\n") for row in budget_rows]
    total_rows = np.asarray([int(row["total_rows"]) for row in budget_rows], dtype=float)
    implemented = np.asarray([1.0 if row["implemented_in_v047"] == "True" else 0.0 for row in budget_rows])
    xs = np.arange(len(labels))
    fig, axes = plt.subplots(1, 2, figsize=(12.0, 4.2))
    axes[0].bar(xs, total_rows, color="#4c6f91")
    axes[0].axhline(DIM, color="#555555", linestyle="--", linewidth=1.0, label="132 row budget")
    axes[0].set_ylabel("rows")
    axes[0].set_title(f"specified stage rows: {spec.get('total_stage_rows', 0)}")
    axes[0].set_xticks(xs)
    axes[0].set_xticklabels(labels, rotation=42, ha="right", fontsize=7)
    axes[0].legend(fontsize=8)
    axes[1].bar(xs, implemented, color=["#2f7d32" if value else "#b3261e" for value in implemented])
    axes[1].set_ylim(-0.05, 1.05)
    axes[1].set_ylabel("implemented")
    axes[1].set_title("independent residual implementation")
    axes[1].set_xticks(xs)
    axes[1].set_xticklabels(labels, rotation=42, ha="right", fontsize=7)
    for ax in axes:
        ax.grid(True, axis="y", alpha=0.35)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_stage_functional_spec_audit.png", dpi=180)
    plt.close(fig)


def plot_endpoint_tfe_stage_functional_implementation_audit(implementation: dict) -> None:
    import matplotlib.pyplot as plt

    cases = implementation.get("cases", {})
    if not cases:
        return
    block_names = [name for name, _, _ in STAGE_FUNCTIONAL_BLOCK_LAYOUT]
    labels = [name.replace("_", "\n") for name in block_names]
    fig, axes = plt.subplots(1, 2, figsize=(12.0, 4.2))
    xs = np.arange(len(block_names))
    width = 0.36
    for idx, (case_name, case) in enumerate(sorted(cases.items())):
        values = [
            max(case.get("block_summaries", {}).get(block_name, {}).get("max_block_equivalence_norm", np.nan), 1.0e-30)
            for block_name in block_names
        ]
        axes[0].bar(xs + (idx - 0.5) * width, values, width=width, label=case_name)
    axes[0].set_yscale("log")
    axes[0].set_ylabel("max block equivalence norm")
    axes[0].set_title("independent assembly vs weighted Gauss6 blocks")
    axes[0].set_xticks(xs)
    axes[0].set_xticklabels(labels, rotation=42, ha="right", fontsize=7)
    axes[0].legend(fontsize=8)
    case_labels = list(sorted(cases))
    residuals = [max(cases[name]["max_independent_stage_functional_residual_norm"], 1.0e-30) for name in case_labels]
    equivalence = [max(cases[name]["max_stage_functional_equivalence_norm"], 1.0e-30) for name in case_labels]
    case_xs = np.arange(len(case_labels))
    axes[1].bar(case_xs - 0.18, residuals, width=0.36, label="independent residual")
    axes[1].bar(case_xs + 0.18, equivalence, width=0.36, label="equivalence error")
    axes[1].set_yscale("log")
    axes[1].set_ylabel("norm")
    axes[1].set_title("h-sweep maxima")
    axes[1].set_xticks(case_xs)
    axes[1].set_xticklabels(case_labels, rotation=20, ha="right", fontsize=8)
    axes[1].legend(fontsize=8)
    for ax in axes:
        ax.grid(True, axis="y", alpha=0.35)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_stage_functional_implementation_audit.png", dpi=180)
    plt.close(fig)


