def plot_endpoint_tfe_stage_probe_source_budget_audit(source_budget: dict) -> None:
    import matplotlib.pyplot as plt

    cases = source_budget.get("cases", {})
    if not cases:
        return
    fig, axes = plt.subplots(1, 2, figsize=(11.0, 4.2))
    for case_name, case in sorted(cases.items()):
        rows = sorted(case.get("runs", []), key=lambda row: float(row["h"]), reverse=True)
        if not rows:
            continue
        label = case_name.replace("cylindrical_", "")
        h_values = np.asarray([float(row["h"]) for row in rows], dtype=float)
        source_l2 = np.asarray([float(row["source_l2_budget_norm"]) for row in rows], dtype=float)
        lifted_l2 = np.asarray([float(row["lifted_l2_budget_norm"]) for row in rows], dtype=float)
        dominant_fraction = np.asarray([float(row["dominant_source_fraction"]) for row in rows], dtype=float)
        axes[0].loglog(h_values, np.maximum(source_l2, 1.0e-300), "o-", label=f"{label} source L2")
        axes[0].loglog(h_values, np.maximum(lifted_l2, 1.0e-300), "s--", label=f"{label} lifted L2")
        axes[1].semilogx(h_values, dominant_fraction, "o-", label=label)
    axes[0].set_ylabel("budget norm")
    axes[0].set_title("source budget and lifted probe budget")
    axes[1].set_ylabel("dominant source fraction")
    axes[1].set_ylim(0.0, 1.05)
    axes[1].set_title("dominant weak-row source family")
    for ax in axes:
        ax.set_xlabel("h")
        ax.grid(True, which="both", alpha=0.35)
        ax.invert_xaxis()
        ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_stage_probe_source_budget_audit.png", dpi=180)
    plt.close(fig)


