def plot_endpoint_tfe_full_stage_acceptance_gap_audit(acceptance_gap: dict) -> None:
    import matplotlib.pyplot as plt

    rows = acceptance_gap.get("rows", [])
    if not rows:
        return
    fig, axes = plt.subplots(1, 2, figsize=(11.2, 4.2))
    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
    for case_name, case_rows in sorted(by_case.items()):
        ordered = sorted(case_rows, key=lambda row: float(row["h"]), reverse=True)
        h_values = np.asarray([float(row["h"]) for row in ordered], dtype=float)
        residuals = np.asarray([float(row["proxy_residual_norm"]) for row in ordered], dtype=float)
        probes = np.asarray([float(row["proxy_formula_probe_norm"]) for row in ordered], dtype=float)
        label = case_name.replace("cylindrical_", "")
        axes[0].loglog(h_values, np.maximum(residuals, 1.0e-300), "o-", label=f"{label} proxy residual")
        axes[0].loglog(h_values, np.maximum(probes, 1.0e-300), "s--", label=f"{label} proxy probe")
    labels = [
        "proxy\nsolved",
        "h-sweep",
        "ASME",
        "row\nbudget",
        "source\nremoved",
        "full\nTFE",
    ]
    values = [
        1.0 if acceptance_gap.get("proxy_residual_solved") else 0.0,
        1.0 if acceptance_gap.get("h_sweep_present") else 0.0,
        1.0 if acceptance_gap.get("four_asme_gate_compatible") else 0.0,
        1.0 if acceptance_gap.get("stage_row_budget") == DIM else 0.0,
        1.0 if acceptance_gap.get("endpoint_boundary_source_removed") else 0.0,
        1.0 if acceptance_gap.get("full_tfe_stage_replacement") else 0.0,
    ]
    axes[1].bar(np.arange(len(labels)), values, color=["#2f7d32" if value else "#b3261e" for value in values])
    axes[0].set_ylabel("norm")
    axes[0].set_title("current proxy over accepted h-sweep")
    axes[1].set_ylim(-0.05, 1.05)
    axes[1].set_ylabel("criterion met")
    axes[1].set_title("full-stage acceptance gap")
    axes[1].set_xticks(np.arange(len(labels)))
    axes[1].set_xticklabels(labels, fontsize=8)
    for ax in axes:
        ax.grid(True, which="both", alpha=0.35)
    axes[0].invert_xaxis()
    axes[0].set_xlabel("h")
    axes[0].legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_full_stage_acceptance_gap_audit.png", dpi=180)
    plt.close(fig)


def plot_endpoint_tfe_stage_local_source_removal_target_audit(target_audit: dict) -> None:
    import matplotlib.pyplot as plt

    rows = target_audit.get("rows", [])
    if not rows:
        return
    fig, axes = plt.subplots(1, 2, figsize=(12.0, 4.4))
    blocks = [name for name, _, _ in STAGE_FUNCTIONAL_BLOCK_LAYOUT]
    markers = ["o", "s", "^", "D", "v", "P"]
    for case_name in sorted({row["case"] for row in rows}):
        for idx, block in enumerate(blocks):
            block_rows = [
                row for row in rows
                if row["case"] == case_name and row["block"] == block
            ]
            if not block_rows:
                continue
            block_rows = sorted(block_rows, key=lambda row: float(row["h"]), reverse=True)
            h_values = np.asarray([float(row["h"]) for row in block_rows], dtype=float)
            source_norms = np.asarray([float(row["endpoint_source_norm"]) for row in block_rows], dtype=float)
            label = f"{case_name.replace('cylindrical_', '')} {block.split('_')[0]}"
            axes[0].loglog(
                h_values,
                np.maximum(source_norms, 1.0e-300),
                marker=markers[idx % len(markers)],
                linewidth=1.0,
                markersize=4.0,
                label=label,
            )
    labels = [
        "boundary\nquantified",
        "target\nmapped",
        "replacement\nrequired",
        "source\nremoved",
        "derived\nrows",
        "full\nTFE",
    ]
    values = [
        1.0 if target_audit.get("status") == "stage_local_source_removal_target_quantified_not_full_tfe" else 0.0,
        1.0 if target_audit.get("target_sources") else 0.0,
        1.0 if target_audit.get("stage_local_replacement_required") else 0.0,
        1.0 if target_audit.get("endpoint_boundary_source_removed") else 0.0,
        1.0 if target_audit.get("derived_stage_local_sources_present") else 0.0,
        1.0 if target_audit.get("full_tfe_stage_replacement") else 0.0,
    ]
    axes[1].bar(np.arange(len(labels)), values, color=["#2f7d32" if value else "#b3261e" for value in values])
    axes[0].set_title("source-removal targets by weak row family")
    axes[0].set_xlabel("h")
    axes[0].set_ylabel("endpoint-boundary source norm")
    axes[0].invert_xaxis()
    axes[0].grid(True, which="both", alpha=0.35)
    axes[0].legend(fontsize=6, ncol=2)
    axes[1].set_title("target audit status")
    axes[1].set_ylim(-0.05, 1.05)
    axes[1].set_ylabel("criterion met")
    axes[1].set_xticks(np.arange(len(labels)))
    axes[1].set_xticklabels(labels, fontsize=8)
    axes[1].grid(True, axis="y", alpha=0.35)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_stage_local_source_removal_target_audit.png", dpi=180)
    plt.close(fig)


