def plot_endpoint_tfe_paper_derivative_operator_audit(derivative_audit: dict) -> None:
    import matplotlib.pyplot as plt

    rows = derivative_audit.get("rows", [])
    if not rows:
        return
    rows = sorted(rows, key=lambda row: float(row["h"]), reverse=True)
    h_values = np.asarray([float(row["h"]) for row in rows], dtype=float)
    y_errors = np.asarray([float(row["quadratic_y_reproduction_error"]) for row in rows], dtype=float)
    z_errors = np.asarray([float(row["quadratic_z_reproduction_error"]) for row in rows], dtype=float)
    relation = np.asarray([float(row["max_relation_residual_norm"]) for row in rows], dtype=float)
    dim_labels = ["paper x", "paper y/z", "paper xyz", "v047 stage"]
    dim_values = [
        derivative_audit.get("paper_x_unknown_dim", 0),
        derivative_audit.get("paper_yz_derived_dim", 0),
        derivative_audit.get("paper_total_xyz_dim", 0),
        derivative_audit.get("v047_stage_unknown_dim", 0),
    ]
    fig, axes = plt.subplots(1, 2, figsize=(11.4, 4.2))
    axes[0].loglog(h_values, np.maximum(y_errors, 1.0e-300), "o-", label="y derivative")
    axes[0].loglog(h_values, np.maximum(z_errors, 1.0e-300), "s--", label="z derivative")
    axes[0].loglog(h_values, np.maximum(relation, 1.0e-300), "^:", label="relation residual")
    axes[0].set_title("paper derivative operator reproduction")
    axes[0].set_xlabel("h")
    axes[0].set_ylabel("max abs error")
    axes[0].invert_xaxis()
    axes[0].grid(True, which="both", alpha=0.35)
    axes[0].legend(fontsize=8)
    axes[1].bar(np.arange(len(dim_labels)), dim_values, color=["#4c6f91", "#7c6a2f", "#806080", "#555555"])
    axes[1].set_title("nodal operator dimensions")
    axes[1].set_ylabel("scalar dimension")
    axes[1].set_xticks(np.arange(len(dim_labels)))
    axes[1].set_xticklabels(dim_labels, fontsize=8)
