def plot_endpoint_tfe_paper_stage_input_map_audit(input_map: dict) -> None:
    import matplotlib.pyplot as plt

    rows = input_map.get("rows", [])
    if not rows:
        return
    budget_rows = [row for row in rows if int(row["total_rows"]) > 0]
    labels = [row["component"].replace("_", "\n") for row in budget_rows]
    total_rows = np.asarray([int(row["total_rows"]) for row in budget_rows], dtype=float)
    inputs = np.asarray([1.0 if row["paper_inputs_available"] == "True" else 0.0 for row in budget_rows], dtype=float)
    formulas = np.asarray([1.0 if row["stage_local_formula_present"] == "True" else 0.0 for row in budget_rows], dtype=float)
    substituted = np.asarray([1.0 if row["residual_substituted"] == "True" else 0.0 for row in budget_rows], dtype=float)
    x = np.arange(len(labels))
    fig, axes = plt.subplots(1, 2, figsize=(12.0, 4.3))
    axes[0].bar(x, total_rows, color="#4c6f91")
    axes[0].axhline(DIM, color="0.25", lw=1.0, ls="--", label="132 row budget")
    axes[0].set_title("paper input map row coverage")
    axes[0].set_ylabel("rows")
    axes[0].set_xticks(x)
    axes[0].set_xticklabels(labels, rotation=42, ha="right", fontsize=7)
    axes[0].legend(fontsize=8)
    width = 0.24
    axes[1].bar(x - width, inputs, width, label="inputs")
    axes[1].bar(x, formulas, width, label="formula")
    axes[1].bar(x + width, substituted, width, label="substituted")
    axes[1].set_title("replacement readiness by row family")
    axes[1].set_ylim(-0.05, 1.05)
    axes[1].set_ylabel("criterion met")
    axes[1].set_xticks(x)
    axes[1].set_xticklabels(labels, rotation=42, ha="right", fontsize=7)
    axes[1].legend(fontsize=8)
    for ax in axes:
        ax.grid(True, axis="y", alpha=0.35)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_paper_stage_input_map_audit.png", dpi=180)
    plt.close(fig)


def plot_endpoint_tfe_paper_multiplier_policy_audit(policy: dict) -> None:
    import matplotlib.pyplot as plt

    if not policy:
        return
    dim_labels = ["lambda x", "lambda y/z", "v047 lambda"]
    dim_values = [
        policy.get("paper_lambda_x_unknown_dim", 0),
        policy.get("paper_lambda_yz_derived_dim", 0),
        policy.get("v047_stage_lambda_dim", 0),
    ]
    ready_labels = ["policy", "extra rows", "substituted", "full TFE"]
    ready_values = [
        1.0 if policy.get("multiplier_policy_specified", False) else 0.0,
        1.0 if policy.get("lambda_yz_extra_rows_required", 1) == 0 else 0.0,
        1.0 if policy.get("residual_replacement_ready", False) else 0.0,
        1.0 if policy.get("full_tfe_stage_replacement", False) else 0.0,
    ]
    fig, axes = plt.subplots(1, 2, figsize=(10.8, 4.0))
    axes[0].bar(np.arange(len(dim_labels)), dim_values, color=["#4c6f91", "#806080", "#555555"])
    axes[0].set_title("paper multiplier dimensions")
    axes[0].set_ylabel("scalar dimension")
    axes[0].set_xticks(np.arange(len(dim_labels)))
    axes[0].set_xticklabels(dim_labels, fontsize=8)
    axes[0].grid(True, axis="y", alpha=0.35)
    axes[1].bar(np.arange(len(ready_labels)), ready_values, color=["#4c6f91", "#6b8e5a", "#9b6a4f", "#555555"])
    axes[1].set_title("multiplier policy readiness")
    axes[1].set_ylim(-0.05, 1.05)
    axes[1].set_ylabel("criterion met")
    axes[1].set_xticks(np.arange(len(ready_labels)))
    axes[1].set_xticklabels(ready_labels, fontsize=8)
    axes[1].grid(True, axis="y", alpha=0.35)
    fig.tight_layout()
