def plot_endpoint_tfe_paper_kinematic_formula_audit(kinematic_formula: dict) -> None:
    import matplotlib.pyplot as plt

    rows = kinematic_formula.get("rows", [])
    if not rows:
        return
    by_component: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_component.setdefault(row["component"], []).append(row)
    fig, axes = plt.subplots(1, 2, figsize=(11.8, 4.4))
    for component, component_rows in sorted(by_component.items()):
        ordered = sorted(component_rows, key=lambda row: float(row["h"]), reverse=True)
        h_values = np.asarray([float(row["h"]) for row in ordered], dtype=float)
        residuals = np.asarray([float(row["max_formula_residual_norm"]) for row in ordered], dtype=float)
        axes[0].loglog(h_values, np.maximum(residuals, 1.0e-300), "o-", label=component.replace("_weak_defect", ""))
    components = list(sorted(by_component))
    labels = [component.replace("_weak_defect", "").replace("_", "\n") for component in components]
    formulas = np.asarray(
        [
            1.0 if all(row["stage_local_formula_present"] == "True" for row in by_component[component]) else 0.0
            for component in components
        ],
        dtype=float,
    )
    substituted = np.asarray(
        [
            1.0 if all(row["residual_substituted"] == "True" for row in by_component[component]) else 0.0
            for component in components
        ],
        dtype=float,
    )
    width = 0.34
    x = np.arange(len(labels))
    axes[0].set_title("paper kinematic formula residual")
    axes[0].set_xlabel("h")
    axes[0].set_ylabel("norm")
    axes[0].invert_xaxis()
    axes[0].grid(True, which="both", alpha=0.35)
    axes[0].legend(fontsize=7)
    axes[1].bar(x - width / 2, formulas, width, label="formula")
    axes[1].bar(x + width / 2, substituted, width, label="substituted")
    axes[1].set_title("kinematic formula readiness")
    axes[1].set_ylim(-0.05, 1.05)
    axes[1].set_ylabel("criterion met")
    axes[1].set_xticks(x)
    axes[1].set_xticklabels(labels, fontsize=7)
    axes[1].grid(True, axis="y", alpha=0.35)
    axes[1].legend(fontsize=8)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_paper_kinematic_formula_audit.png", dpi=180)
    plt.close(fig)


