def plot_endpoint_tfe_paper_position_substitution_candidate_audit(position_substitution: dict) -> None:
    import matplotlib.pyplot as plt

    rows = position_substitution.get("rows", [])
    if not rows:
        return
    cases = sorted({row["case"] for row in rows})
    fig, axes = plt.subplots(1, 2, figsize=(12, 4))
    for case in cases:
        case_rows = sorted([row for row in rows if row["case"] == case], key=lambda row: float(row["h"]))
        h = np.asarray([float(row["h"]) for row in case_rows], dtype=float)
        pos = np.asarray([float(row["position_error_vs_paper_position_reference"]) for row in case_rows], dtype=float)
        vel = np.asarray([float(row["velocity_error_vs_paper_position_reference"]) for row in case_rows], dtype=float)
        residual = np.asarray([float(row["max_paper_position_substitution_residual_norm"]) for row in case_rows], dtype=float)
        removed = np.asarray([float(row["max_removed_gauss_position_block_norm"]) for row in case_rows], dtype=float)
        axes[0].loglog(h, pos, marker="o", label=f"{case} pos")
        axes[0].loglog(h, vel, marker="s", linestyle="--", label=f"{case} vel")
        axes[1].semilogy(h, residual, marker="o", label=f"{case} paper rows")
        axes[1].semilogy(h, removed, marker="s", linestyle="--", label=f"{case} removed Gauss rows")
    axes[0].invert_xaxis()
    axes[0].set_xlabel("h")
    axes[0].set_ylabel("error vs h=0.005 candidate")
    axes[0].set_title("position-row substitution trajectory error")
    axes[0].legend(fontsize=7)
    axes[1].invert_xaxis()
    axes[1].set_xlabel("h")
    axes[1].set_ylabel("row norm")
    axes[1].set_title("substituted vs removed rows")
    axes[1].legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_endpoint_tfe_paper_position_substitution_candidate_audit.png", dpi=180)
