def plot_endpoint_tfe_paper_lower_pair_acceleration_terminal_row_homotopy_audit(homotopy: dict) -> None:
    import matplotlib.pyplot as plt

    rows = homotopy.get("rows", [])
    if not rows:
        return
    cases = sorted({row["case"] for row in rows})
    h_values = sorted({float(row["h"]) for row in rows}, reverse=True)
    fig, axes = plt.subplots(1, 3, figsize=(15.5, 4.1))
    for case in cases:
        for h in h_values:
            case_rows = sorted(
                [
                    row for row in rows
                    if row["case"] == case and abs(float(row["h"]) - h) < 1.0e-15
                ],
                key=lambda row: float(row["beta"]),
            )
            if not case_rows:
                continue
            beta = np.asarray([float(row["beta"]) for row in case_rows], dtype=float)
            residual = np.asarray([float(row["residual_norm"]) for row in case_rows], dtype=float)
            terminal_vel = np.asarray(
                [float(row["terminal_endpoint_velocity_constraint_norm"]) for row in case_rows],
                dtype=float,
            )
            acceleration = np.asarray(
                [float(row["terminal_lower_pair_acceleration_row_norm"]) for row in case_rows],
                dtype=float,
            )
            velocity_row = np.asarray([float(row["terminal_velocity_row_norm"]) for row in case_rows], dtype=float)
            raw_condition = np.asarray([float(row["raw_jacobian_condition"]) for row in case_rows], dtype=float)
            scaled_condition = np.asarray([float(row["scaled_jacobian_condition"]) for row in case_rows], dtype=float)
            label = f"{case.replace('cylindrical_', '')} h={h:g}"
            axes[0].semilogy(beta, np.maximum(terminal_vel, 1.0e-300), marker="o", label=label)
            axes[0].semilogy(beta, np.maximum(residual, 1.0e-300), marker="s", linestyle="--")
            axes[1].semilogy(beta, np.maximum(acceleration, 1.0e-300), marker="o", label=f"{label} accel")
            axes[1].semilogy(beta, np.maximum(velocity_row, 1.0e-300), marker="s", linestyle="--", label=f"{label} velrow")
            axes[2].semilogy(beta, np.maximum(raw_condition, 1.0e-300), marker="o", label=f"{label} raw")
            axes[2].semilogy(beta, np.maximum(scaled_condition, 1.0e-300), marker="s", linestyle="--", label=f"{label} scaled")
    axes[0].set_ylabel("endpoint velocity residual / Newton residual")
    axes[0].set_title("terminal row homotopy closure")
    axes[1].set_ylabel("terminal row norm")
    axes[1].set_title("acceleration row vs velocity row")
    axes[2].set_ylabel("Jacobian condition")
    axes[2].set_title("homotopy conditioning")
    for ax in axes:
        ax.set_xlabel("beta")
        ax.grid(True, which="both", alpha=0.35)
        ax.legend(fontsize=5)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_acceleration_terminal_row_homotopy_audit.png",
        dpi=180,
    )
    plt.close(fig)


