def plot_endpoint_tfe_paper_lower_pair_terminal_source_insertion_audit(source_insertion: dict) -> None:
    import matplotlib.pyplot as plt

    rows = source_insertion.get("rows", [])
    if not rows:
        return

    def finite_positive(values: list[float]) -> np.ndarray:
        arr = np.asarray(values, dtype=float)
        return np.where(np.isfinite(arr), np.maximum(arr, 1.0e-300), np.nan)

    cases = sorted({row["case"] for row in rows})
    signs = sorted({float(row["source_sign"]) for row in rows})
    fig, axes = plt.subplots(1, 3, figsize=(15.5, 4.1))
    for case in cases:
        for sign in signs:
            case_rows = sorted(
                [
                    row
                    for row in rows
                    if row["case"] == case and abs(float(row["source_sign"]) - sign) < 1.0e-15
                ],
                key=lambda row: float(row["h"]),
            )
            if not case_rows:
                continue
            h = np.asarray([float(row["h"]) for row in case_rows], dtype=float)
            residual = finite_positive([float(row["residual_norm"]) for row in case_rows])
            velocity = finite_positive([float(row["terminal_endpoint_velocity_constraint_norm"]) for row in case_rows])
            lower_block = finite_positive([float(row["lower_pair_inserted_block_norm"]) for row in case_rows])
            label = f"{case.replace('cylindrical_', '')} sign {sign:+.0f}"
            axes[0].loglog(h, residual, marker="o", label=label)
            axes[1].loglog(h, velocity, marker="s", linestyle="--", label=label)
            axes[2].loglog(h, lower_block, marker="^", linestyle=":", label=label)
    axes[0].set_ylabel("residual norm")
    axes[0].set_title("source-inserted Newton residual")
    axes[1].set_ylabel("endpoint velocity norm")
    axes[1].set_title("terminal velocity after insertion")
    axes[2].set_ylabel("lower-pair block norm")
    axes[2].set_title("inserted lower-pair rows")
    for ax in axes:
        ax.invert_xaxis()
        ax.set_xlabel("h")
        ax.grid(True, which="both", alpha=0.35)
        ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_terminal_source_insertion_audit.png",
        dpi=180,
    )
    plt.close(fig)


