def plot_endpoint_tfe_paper_lower_pair_terminal_source_insertion_blowup_audit(blowup: dict) -> None:
    import matplotlib.pyplot as plt

    rows = blowup.get("rows", [])
    if not rows:
        return

    display_metrics = [
        "max_normalized_source_norm",
        "max_terminal_endpoint_velocity_constraint_norm",
        "max_terminal_z0_update_delta_norm",
        "max_raw_jacobian_condition",
    ]
    fig, axes = plt.subplots(1, 4, figsize=(20.0, 4.1))
    for ax, metric in zip(axes, display_metrics):
        metric_rows = [row for row in rows if row["metric"] == metric]
        for row in metric_rows:
            h = np.asarray(
                [float(row["h_coarse"]), float(row["h_mid"]), float(row["h_fine"])],
                dtype=float,
            )
            values = np.asarray(
                [float(row["value_coarse"]), float(row["value_mid"]), float(row["value_fine"])],
                dtype=float,
            )
            values = np.where(np.isfinite(values), np.maximum(values, 1.0e-300), np.nan)
            label = row["case"].replace("cylindrical_", "")
            ax.loglog(h, values, marker="o", label=f"{label} p={float(row['observed_power_h']):.2f}")
        ax.invert_xaxis()
        ax.set_xlabel("h")
        ax.set_ylabel(metric)
        ax.set_title(metric.replace("max_", "").replace("_", " "))
        ax.grid(True, which="both", alpha=0.35)
        ax.legend(fontsize=6)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_terminal_source_insertion_blowup_audit.png",
        dpi=180,
    )
    plt.close(fig)


def plot_endpoint_tfe_paper_lower_pair_terminal_source_bounded_policy_audit(bounded_policy: dict) -> None:
    import matplotlib.pyplot as plt

    rows = bounded_policy.get("rows", [])
    if not rows:
        return
    source_rows = [row for row in rows if row.get("source_policy_rejected") == "True"]
    if not source_rows:
        source_rows = rows
    labels = []
    for row in source_rows:
        case_label = row["case"].replace("cylindrical_", "")
        metric_label = row["metric"].replace("max_", "").replace("_", "\n")
        labels.append(f"{case_label}\n{metric_label}")
    missing = np.asarray([float(row["missing_h_power_to_bounded"]) for row in source_rows], dtype=float)
    excess = np.asarray([float(row["excess_missing_power_vs_condition"]) for row in source_rows], dtype=float)
    h2_power = np.asarray([float(row["power_after_extra_h2"]) for row in source_rows], dtype=float)
    xs = np.arange(len(labels))
    fig, axes = plt.subplots(1, 2, figsize=(13.5, 4.6))
    axes[0].bar(xs - 0.18, missing, width=0.36, label="missing h power")
    axes[0].bar(xs + 0.18, excess, width=0.36, label="excess over condition")
    axes[0].axhline(2.0, color="black", linewidth=1.0, alpha=0.45, label="h^2 repair")
    axes[0].set_ylabel("h-power")
    axes[0].set_title("bounded source target")
    axes[0].set_xticks(xs)
    axes[0].set_xticklabels(labels, rotation=50, ha="right", fontsize=6)
    axes[1].bar(xs, h2_power, width=0.5, color="#7a4f9a")
    axes[1].axhline(0.0, color="black", linewidth=1.0, alpha=0.6)
    axes[1].set_ylabel("observed power after extra h^2")
    axes[1].set_title("simple h^2 scaling remains unbounded when below zero")
    axes[1].set_xticks(xs)
    axes[1].set_xticklabels(labels, rotation=50, ha="right", fontsize=6)
    for ax in axes:
        ax.grid(True, axis="y", alpha=0.35)
        handles, legend_labels = ax.get_legend_handles_labels()
        if handles:
            ax.legend(handles, legend_labels, fontsize=7)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_terminal_source_bounded_policy_audit.png",
        dpi=180,
    )
    plt.close(fig)


