def plot_endpoint_tfe_paper_lower_pair_source_free_order_closure_blend_trajectory_audit(audit: dict) -> None:
    import matplotlib.pyplot as plt

    rows = audit.get("rows", [])
    if not rows:
        return
    betas = sorted({float(row["beta"]) for row in rows})
    cases = sorted({row["case"] for row in rows})
    fig, axes = plt.subplots(1, 3, figsize=(15.8, 4.2))
    for case in cases:
        terminal_by_beta = []
        pos_order_by_beta = []
        vel_order_by_beta = []
        for beta in betas:
            beta_rows = [
                row
                for row in rows
                if row["case"] == case and abs(float(row["beta"]) - beta) < 1.0e-12
            ]
            if not beta_rows:
                terminal_by_beta.append(float("nan"))
                pos_order_by_beta.append(float("nan"))
                vel_order_by_beta.append(float("nan"))
                continue
            terminal_by_beta.append(
                max(float(row["max_raw_terminal_endpoint_velocity_constraint_norm"]) for row in beta_rows)
            )
            pos_order_by_beta.append(float(beta_rows[0]["position_observed_order"]))
            vel_order_by_beta.append(float(beta_rows[0]["velocity_observed_order"]))
        label = case.replace("cylindrical_", "")
        axes[0].semilogy(betas, np.maximum(terminal_by_beta, 1.0e-300), "o-", label=label)
        axes[1].plot(betas, pos_order_by_beta, "o-", label=f"{label} pos")
        axes[1].plot(betas, vel_order_by_beta, "s--", label=f"{label} vel")
        for beta in betas:
            beta_rows = sorted(
                [
                    row
                    for row in rows
                    if row["case"] == case and abs(float(row["beta"]) - beta) < 1.0e-12
                ],
                key=lambda row: float(row["h"]),
            )
            if not beta_rows:
                continue
            h = np.asarray([float(row["h"]) for row in beta_rows], dtype=float)
            position_error = np.asarray(
                [float(row["position_error_vs_source_free_order_closure_blend_reference"]) for row in beta_rows],
                dtype=float,
            )
            axes[2].loglog(h, np.maximum(position_error, 1.0e-300), "o-", label=f"{label} beta={beta:g}")
    axes[0].axhline(1.0e-10, color="black", linestyle=":", linewidth=1.0, label="terminal tol")
    axes[1].axhline(5.0, color="black", linestyle=":", linewidth=1.0, label="paper target")
    axes[0].set_title("terminal velocity vs beta")
    axes[0].set_xlabel("beta")
    axes[0].set_ylabel("max raw endpoint velocity")
    axes[1].set_title("observed order vs beta")
    axes[1].set_xlabel("beta")
    axes[1].set_ylabel("order")
    axes[2].set_title("position h-sweep")
    axes[2].set_xlabel("h")
    axes[2].set_ylabel("error vs h=0.005")
    axes[2].invert_xaxis()
    for ax in axes:
        ax.grid(True, which="both", alpha=0.35)
        ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_source_free_order_closure_blend_trajectory_audit.png",
        dpi=180,
    )
    plt.close(fig)


def plot_endpoint_tfe_paper_lower_pair_source_free_mean_blend_closure_audit(mean_blend: dict) -> None:
    import matplotlib.pyplot as plt

    rows = mean_blend.get("rows", [])
    if not rows:
        return

    def finite_positive(values: list[float]) -> np.ndarray:
        arr = np.asarray(values, dtype=float)
        return np.where(np.isfinite(arr), np.maximum(arr, 1.0e-300), np.nan)

    alphas = sorted({float(row["alpha"]) for row in rows})
    cases = sorted({row["case"] for row in rows})
    fig, axes = plt.subplots(1, 3, figsize=(16.5, 4.4))
    for case in cases:
        for h in sorted({float(row["h"]) for row in rows if row["case"] == case}):
            case_h_rows = sorted(
                [
                    row
                    for row in rows
                    if row["case"] == case and abs(float(row["h"]) - h) < 1.0e-15
                ],
                key=lambda row: float(row["alpha"]),
            )
            if not case_h_rows:
                continue
            alpha = np.asarray([float(row["alpha"]) for row in case_h_rows], dtype=float)
            velocity = finite_positive(
                [float(row["raw_terminal_endpoint_velocity_constraint_norm"]) for row in case_h_rows]
            )
            residual = finite_positive([float(row["residual_norm"]) for row in case_h_rows])
            label = f"{case.replace('cylindrical_', '')} h={h:g}"
            axes[0].semilogy(alpha, velocity, marker="o", label=label)
            axes[1].semilogy(alpha, residual, marker="s", linestyle="--", label=label)
    for case in cases:
        best = []
        for alpha in alphas:
            alpha_case_rows = [
                row
                for row in rows
                if row["case"] == case and abs(float(row["alpha"]) - alpha) < 1.0e-15
            ]
            best.append(
                max(
                    [float(row["raw_terminal_endpoint_velocity_constraint_norm"]) for row in alpha_case_rows],
                    default=float("nan"),
                )
            )
        axes[2].semilogy(alphas, finite_positive(best), marker="^", label=case.replace("cylindrical_", ""))
    axes[0].axhline(1.0e-10, color="black", linestyle=":", linewidth=1.0)
    axes[0].set_ylabel("one-step terminal velocity norm")
    axes[0].set_title("source-free blend terminal closure")
    axes[1].axhline(1.0e-8, color="black", linestyle=":", linewidth=1.0)
    axes[1].set_ylabel("Newton residual norm")
    axes[1].set_title("residual by alpha")
    axes[2].axhline(1.0e-10, color="black", linestyle=":", linewidth=1.0)
    axes[2].set_ylabel("max terminal velocity over h")
    axes[2].set_title("worst h per alpha")
    for ax in axes:
        ax.set_xlabel("alpha")
        ax.grid(True, which="both", alpha=0.35)
        ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_source_free_mean_blend_closure_audit.png",
        dpi=180,
    )
    plt.close(fig)


def plot_endpoint_tfe_paper_lower_pair_source_free_mean_blend_trajectory_audit(trajectory: dict) -> None:
    import matplotlib.pyplot as plt

    rows = trajectory.get("rows", [])
    if not rows:
        return
    cases = sorted({row["case"] for row in rows})
    fig, axes = plt.subplots(1, 3, figsize=(15.8, 4.3))
    for case in cases:
        case_rows = sorted([row for row in rows if row["case"] == case], key=lambda row: float(row["h"]))
        if not case_rows:
            continue
        h = np.asarray([float(row["h"]) for row in case_rows], dtype=float)
        position_error = np.asarray(
            [float(row["position_error_vs_source_free_mean_blend_reference"]) for row in case_rows],
            dtype=float,
        )
        velocity_error = np.asarray(
            [float(row["velocity_error_vs_source_free_mean_blend_reference"]) for row in case_rows],
            dtype=float,
        )
        residual = np.asarray([float(row["max_residual_norm"]) for row in case_rows], dtype=float)
        source_consistency = np.asarray(
            [float(row["max_source_consistency_row_norm"]) for row in case_rows],
            dtype=float,
        )
        blend_mean_rows = np.asarray(
            [float(row["max_blend_mean_closure_row_norm"]) for row in case_rows],
            dtype=float,
        )
        terminal_velocity = np.asarray(
            [float(row["max_raw_terminal_endpoint_velocity_constraint_norm"]) for row in case_rows],
            dtype=float,
        )
        label = case.replace("cylindrical_", "")
        axes[0].loglog(h, np.maximum(position_error, 1.0e-300), "o-", label=f"{label} pos")
        axes[0].loglog(h, np.maximum(velocity_error, 1.0e-300), "s--", label=f"{label} vel")
        axes[1].loglog(h, np.maximum(source_consistency, 1.0e-300), "o-", label=f"{label} source consistency")
        axes[1].loglog(h, np.maximum(blend_mean_rows, 1.0e-300), "s--", label=f"{label} blend mean")
        axes[2].loglog(h, np.maximum(residual, 1.0e-300), "o-", label=f"{label} residual")
        axes[2].loglog(h, np.maximum(terminal_velocity, 1.0e-300), "s--", label=f"{label} terminal vel")
    axes[0].set_ylabel("error vs h=0.005")
    axes[0].set_title("source-free blend trajectory")
    axes[1].set_ylabel("row norm")
    axes[1].set_title("24 lower-pair replacement rows")
    axes[2].axhline(1.0e-10, color="tab:orange", linestyle=":", linewidth=1.0)
    axes[2].axhline(1.0e-8, color="tab:blue", linestyle=":", linewidth=1.0)
    axes[2].set_ylabel("norm")
    axes[2].set_title("residual and raw endpoint velocity")
    for ax in axes:
        ax.set_xlabel("h")
        ax.grid(True, which="both", alpha=0.35)
        ax.invert_xaxis()
        ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_source_free_mean_blend_trajectory_audit.png",
        dpi=180,
    )
    plt.close(fig)


def plot_endpoint_tfe_paper_lower_pair_source_free_mean_blend_trajectory_alpha_sweep_audit(
    alpha_sweep: dict,
) -> None:
    import matplotlib.pyplot as plt

    rows = alpha_sweep.get("rows", [])
    if not rows:
        return
    alpha_values = sorted({float(row["alpha"]) for row in rows})
    terminal_velocity = []
    residual = []
    min_order = []
    for alpha in alpha_values:
        alpha_rows = [row for row in rows if abs(float(row["alpha"]) - alpha) < 1.0e-15]
        terminal_velocity.append(
            max(float(row["max_raw_terminal_endpoint_velocity_constraint_norm"]) for row in alpha_rows)
        )
        residual.append(max(float(row["max_residual_norm"]) for row in alpha_rows))
        min_order.append(
            min(
                min(float(row["position_observed_order"]), float(row["velocity_observed_order"]))
                for row in alpha_rows
            )
        )
    x = np.asarray(alpha_values, dtype=float)
    fig, axes = plt.subplots(1, 3, figsize=(15.8, 4.3))
    axes[0].semilogy(x, np.maximum(np.asarray(terminal_velocity), 1.0e-300), "o-", label="terminal velocity")
    axes[0].axhline(1.0e-10, color="black", linestyle=":", linewidth=1.0)
    axes[0].set_ylabel("max raw terminal velocity")
    axes[0].set_title("trajectory alpha terminal gate")
    axes[1].semilogy(x, np.maximum(np.asarray(residual), 1.0e-300), "o-", color="tab:blue", label="residual")
    axes[1].axhline(1.0e-8, color="black", linestyle=":", linewidth=1.0)
    axes[1].set_ylabel("max residual")
    axes[1].set_title("Newton residual by alpha")
    axes[2].plot(x, min_order, "o-", color="tab:green", label="min observed order")
    axes[2].axhline(1.8, color="black", linestyle=":", linewidth=1.0)
    axes[2].set_ylabel("min position/velocity order")
    axes[2].set_title("order floor by alpha")
    for ax in axes:
        ax.set_xlabel("alpha")
        ax.grid(True, which="both", alpha=0.35)
        ax.legend(fontsize=8)
    fig.tight_layout()
    fig.savefig(
        RESULTS
        / "cylindrical_chain_endpoint_tfe_paper_lower_pair_source_free_mean_blend_trajectory_alpha_sweep_audit.png",
        dpi=180,
    )
    plt.close(fig)


