def plot_endpoint_tfe_paper_lower_pair_velocity_compression_bounded_gradient_audit(audit: dict) -> None:
    import matplotlib.pyplot as plt

    rows = audit.get("bounded_gradient_rows", [])
    if not rows:
        return
    caps = sorted({float(row["gradient_cap"]) for row in rows})
    max_residuals = []
    span_counts = []
    min_fraction = []
    for cap in caps:
        cap_rows = [row for row in rows if abs(float(row["gradient_cap"]) - cap) <= max(1.0, cap) * 1.0e-12]
        residuals = [
            float(row["projection_relative_residual"])
            for row in cap_rows
            if row["projection_relative_residual"] != "nan"
        ]
        fractions = [
            float(row["applied_derivative_fraction"])
            for row in cap_rows
            if row["applied_derivative_fraction"] != "nan"
        ]
        max_residuals.append(max(residuals, default=float("nan")))
        span_counts.append(sum(row["bounded_gradient_cap_spans_target"] == "True" for row in cap_rows))
        min_fraction.append(min(fractions, default=float("nan")))
    fig, axes = plt.subplots(1, 3, figsize=(15.5, 4.4))
    axes[0].plot(caps, np.maximum(np.asarray(max_residuals, dtype=float), 1.0e-300), marker="o")
    axes[0].set_xscale("log")
    axes[0].set_yscale("log")
    axes[0].axhline(1.0e-8, color="black", linestyle=":", linewidth=1.0)
    axes[0].set_xlabel("coefficient-gradient Frobenius cap")
    axes[0].set_ylabel("max projection residual")
    axes[0].set_title("cap-limited tangent closure")
    axes[1].plot(caps, span_counts, marker="o")
    axes[1].set_xscale("log")
    axes[1].axhline(36, color="black", linestyle=":", linewidth=1.0)
    axes[1].set_xlabel("coefficient-gradient Frobenius cap")
    axes[1].set_ylabel("spanning rows")
    axes[1].set_title("rows below span threshold")
    axes[2].plot(caps, np.maximum(np.asarray(min_fraction, dtype=float), 1.0e-300), marker="o")
    axes[2].set_xscale("log")
    axes[2].set_yscale("log")
    axes[2].axhline(1.0, color="black", linestyle=":", linewidth=1.0)
    axes[2].set_xlabel("coefficient-gradient Frobenius cap")
    axes[2].set_ylabel("min applied derivative fraction")
    axes[2].set_title("oracle fraction admitted")
    for ax in axes:
        ax.grid(True, which="both", alpha=0.35)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_velocity_compression_bounded_gradient_audit.png",
        dpi=180,
    )
    plt.close(fig)


def plot_endpoint_tfe_paper_lower_pair_velocity_compression_bounded_formula_audit(audit: dict) -> None:
    import matplotlib.pyplot as plt

    rows = audit.get("bounded_formula_rows", [])
    if not rows:
        return
    laws = []
    for row in rows:
        law = row["analytic_saturation_law"]
        if law not in laws:
            laws.append(law)
    caps = sorted({float(row["gradient_cap"]) for row in rows})
    fig, axes = plt.subplots(1, 3, figsize=(16.5, 4.6))
    for law in laws:
        max_residuals = []
        span_counts = []
        min_fractions = []
        for cap in caps:
            cap_rows = [
                row
                for row in rows
                if row["analytic_saturation_law"] == law
                and abs(float(row["gradient_cap"]) - cap) <= max(1.0, cap) * 1.0e-12
            ]
            residuals = [
                float(row["projection_relative_residual"])
                for row in cap_rows
                if row["projection_relative_residual"] != "nan"
            ]
            fractions = [
                float(row["min_applied_derivative_fraction"])
                for row in cap_rows
                if row["min_applied_derivative_fraction"] != "nan"
            ]
            max_residuals.append(max(residuals, default=float("nan")))
            span_counts.append(sum(row["bounded_analytic_formula_spans_target"] == "True" for row in cap_rows))
            min_fractions.append(min(fractions, default=float("nan")))
        label = law.replace("_saturation", "").replace("_", " ")
        axes[0].plot(caps, np.maximum(np.asarray(max_residuals, dtype=float), 1.0e-300), marker="o", label=label)
        axes[1].plot(caps, span_counts, marker="o", label=label)
        axes[2].plot(caps, np.maximum(np.asarray(min_fractions, dtype=float), 1.0e-300), marker="o", label=label)
    axes[0].set_xscale("log")
    axes[0].set_yscale("log")
    axes[0].axhline(1.0e-8, color="black", linestyle=":", linewidth=1.0)
    axes[0].set_xlabel("coefficient-gradient cap")
    axes[0].set_ylabel("max projection residual")
    axes[0].set_title("bounded analytic law residual")
    axes[1].set_xscale("log")
