def plot_endpoint_tfe_paper_lower_pair_velocity_compression_target_free_formula_audit(audit: dict) -> None:
    import matplotlib.pyplot as plt

    rows = audit.get("target_free_formula_rows", [])
    if not rows:
        return
    laws = []
    for row in rows:
        law = row["target_free_direction_law"]
        if law not in laws:
            laws.append(law)
    caps = sorted({float(row["gradient_cap"]) for row in rows})
    fig, axes = plt.subplots(1, 3, figsize=(16.5, 4.6))
    for law in laws:
        max_residuals = []
        span_counts = []
        min_fractions = []
        for cap in caps:
            cap_rows = [
                row
                for row in rows
                if row["target_free_direction_law"] == law
                and abs(float(row["gradient_cap"]) - cap) <= max(1.0, cap) * 1.0e-12
            ]
            residuals = [
                float(row["projection_relative_residual"])
                for row in cap_rows
                if row["projection_relative_residual"] != "nan"
            ]
            fractions = [
                float(row["min_applied_derivative_fraction"])
                for row in cap_rows
                if row["min_applied_derivative_fraction"] != "nan"
            ]
            max_residuals.append(max(residuals, default=float("nan")))
            span_counts.append(sum(row["target_free_formula_spans_target"] == "True" for row in cap_rows))
            min_fractions.append(min(fractions, default=float("nan")))
        label = law.replace("_perp", "").replace("_", " ")
        axes[0].plot(caps, np.maximum(np.asarray(max_residuals, dtype=float), 1.0e-300), marker="o", label=label)
        axes[1].plot(caps, span_counts, marker="o", label=label)
        axes[2].plot(caps, np.maximum(np.asarray(min_fractions, dtype=float), 1.0e-300), marker="o", label=label)
    axes[0].set_xscale("log")
    axes[0].set_yscale("log")
    axes[0].axhline(1.0e-8, color="black", linestyle=":", linewidth=1.0)
    axes[0].set_xlabel("coefficient-gradient row cap")
    axes[0].set_ylabel("max projection residual")
    axes[0].set_title("target-free law residual")
    axes[1].set_xscale("log")
    axes[1].axhline(36, color="black", linestyle=":", linewidth=1.0)
    axes[1].set_xlabel("coefficient-gradient row cap")
    axes[1].set_ylabel("spanning rows")
    axes[1].set_title("rows below span threshold")
    axes[2].set_xscale("log")
    axes[2].set_yscale("log")
    axes[2].axhline(1.0, color="black", linestyle=":", linewidth=1.0)
    axes[2].set_xlabel("coefficient-gradient row cap")
    axes[2].set_ylabel("min applied fraction")
    axes[2].set_title("target-free correction admitted")
    for ax in axes:
        ax.grid(True, which="both", alpha=0.35)
    axes[0].legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_velocity_compression_target_free_formula_audit.png",
        dpi=180,
    )
    plt.close(fig)


def plot_endpoint_tfe_paper_lower_pair_velocity_compression_row_space_compression_audit(audit: dict) -> None:
    import matplotlib.pyplot as plt

    rows = audit.get("row_space_compression_rows", [])
    if not rows:
        return
    laws = []
    for row in rows:
        law = row["row_space_compression_law"]
        if law not in laws:
            laws.append(law)
    labels = [law.replace("_", "\n") for law in laws]
    max_projection = []
    max_value_residual = []
    span_counts = []
    nonfinal_counts = []
    for law in laws:
        law_rows = [row for row in rows if row["row_space_compression_law"] == law]
        projections = [
            float(row["projection_relative_residual"])
            for row in law_rows
            if row["projection_relative_residual"] != "nan"
        ]
        value_residuals = [
            float(row["value_residual_norm"])
            for row in law_rows
            if row["value_residual_norm"] != "nan"
        ]
        max_projection.append(max(projections, default=float("nan")))
        max_value_residual.append(max(value_residuals, default=float("nan")))
        span_counts.append(sum(row["row_space_compression_spans_target"] == "True" for row in law_rows))
        nonfinal_counts.append(sum(row["uses_final_stage_velocity_feature"] == "False" for row in law_rows))
    x = np.arange(len(laws))
    fig, axes = plt.subplots(1, 3, figsize=(17.5, 4.8))
    axes[0].bar(x, np.maximum(np.asarray(max_projection, dtype=float), 1.0e-300))
    axes[0].set_yscale("log")
    axes[0].axhline(1.0e-8, color="black", linestyle=":", linewidth=1.0)
    axes[0].set_ylabel("max projection residual")
    axes[0].set_title("frozen row-space tangent closure")
    axes[1].bar(x, np.maximum(np.asarray(max_value_residual, dtype=float), 1.0e-300))
    axes[1].set_yscale("log")
    axes[1].axhline(1.0e-8, color="black", linestyle=":", linewidth=1.0)
    axes[1].set_ylabel("max value residual")
    axes[1].set_title("value balance")
    axes[2].bar(x - 0.18, span_counts, width=0.36, label="spans")
    axes[2].bar(x + 0.18, nonfinal_counts, width=0.36, label="nonfinal")
    axes[2].axhline(len(CASES) * len(CONVERGENCE_H_VALUES), color="black", linestyle=":", linewidth=1.0)
    axes[2].set_ylabel("case/h rows")
    axes[2].set_title("span and final-stage usage")
    axes[2].legend(fontsize=8)
    for ax in axes:
        ax.set_xticks(x)
        ax.set_xticklabels(labels, rotation=35, ha="right", fontsize=6.5)
        ax.grid(True, axis="y", alpha=0.35)
    fig.tight_layout()
    fig.savefig(
        RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_velocity_compression_row_space_compression_audit.png",
        dpi=180,
    )
    plt.close(fig)


