def plot_asme_double_reference_policy(asme_gate: dict) -> None:
    import matplotlib.pyplot as plt

    policy = asme_gate.get("method_runs", {}).get("double_pendulum_reference_policy", {})
    if policy.get("status") != "accepted_local_reference_v046_floor_diagnostic":
        return
    fig, axes = plt.subplots(1, 2, figsize=(10.2, 4.0))
    labels = ["self orient", "self omega", "v046 pos", "v046 vel"]
    values = [
        policy["self_orientation_order"],
        policy["self_omega_order"],
        policy["v046_pos_order"],
        policy["v046_vel_order"],
    ]
    colors = ["#2f6fbb", "#2f6fbb", "#9a4d2f", "#9a4d2f"]
    axes[0].bar(labels, values, color=colors)
    axes[0].axhline(5.0, color="black", linestyle="--", linewidth=1.0, label="accepted self-ref threshold")
    axes[0].set_ylabel("observed order")
    axes[0].tick_params(axis="x", rotation=25)
    axes[0].grid(True, axis="y", alpha=0.35)
    axes[0].legend()

    ratio_labels = ["pos floor ratio", "vel floor ratio"]
    ratios = [policy["v046_pos_error_ratio_refined"], policy["v046_vel_error_ratio_refined"]]
    axes[1].bar(ratio_labels, ratios, color=["#6a8f3d", "#6a8f3d"])
    axes[1].axhspan(0.35, 0.65, color="#6a8f3d", alpha=0.18, label="halving band")
    axes[1].set_ylim(0.0, 1.0)
    axes[1].set_ylabel("error ratio after v046 h refinement")
    axes[1].tick_params(axis="x", rotation=20)
    axes[1].grid(True, axis="y", alpha=0.35)
    axes[1].legend()
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_asme_double_reference_policy.png", dpi=180)
    plt.close(fig)


def plot_asme_lower_pair_graph_bridge(asme_gate: dict) -> None:
    import matplotlib.pyplot as plt

    bridge = asme_gate.get("method_runs", {}).get("lower_pair_graph_bridge", {})
    if bridge.get("status") != "ok":
        return
    csv_path = RESULTS / "cylindrical_chain_asme_lower_pair_graph_bridge.csv"
    if not csv_path.exists():
        return
    rows_by_model = {}
    with csv_path.open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if row.get("status") == "ok":
                rows_by_model.setdefault(row["model"], []).append(row)
    if not rows_by_model:
        return

    fig, axes = plt.subplots(1, 2, figsize=(11.0, 4.2))
    markers = ["o", "s", "^", "D"]
    for idx, (model, rows) in enumerate(rows_by_model.items()):
        rows = sorted(rows, key=lambda item: float(item["h"]))
        hs = np.asarray([float(row["h"]) for row in rows], dtype=float)
        pos = np.asarray([float(row["pos_traj_linf"]) for row in rows], dtype=float)
        vel = np.asarray([float(row["vel_traj_linf"]) for row in rows], dtype=float)
        con = np.asarray([float(row["max_position_constraint_norm"]) for row in rows], dtype=float)
        acc_con = np.asarray([float(row["max_acceleration_constraint_norm"]) for row in rows], dtype=float)
        marker = markers[idx % len(markers)]
        label = model.replace("_", " ")
        axes[0].loglog(hs, np.maximum(pos, 1.0e-300), marker=marker, label=f"{label} pos")
        axes[0].loglog(hs, np.maximum(vel, 1.0e-300), marker=marker, linestyle="--", label=f"{label} vel")
        axes[1].loglog(hs, np.maximum(con, 1.0e-300), marker=marker, label=f"{label} Phi")
        axes[1].loglog(hs, np.maximum(acc_con, 1.0e-300), marker=marker, linestyle="--", label=f"{label} acc")
    axes[0].set_ylabel("trajectory Linf error vs nested reference")
    axes[1].set_ylabel("constraint residual norm")
    for ax in axes:
        ax.set_xlabel("h")
        ax.grid(True, which="both", alpha=0.35)
        ax.invert_xaxis()
        ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(RESULTS / "cylindrical_chain_asme_lower_pair_graph_bridge.png", dpi=180)
    plt.close(fig)


