    if kinematic_fullva.get("status") == "ok":
        lines.append(
            "- four_link/slider_crank closed-loop kinematic FullVA solve: "
            f"{kinematic_fullva['mapping_scope']} using `{kinematic_fullva['method']}`; h="
            f"{ASME_CLOSED_LOOP_KINEMATIC_H_VALUES} was checked against a local h="
            f"{ASME_CLOSED_LOOP_KINEMATIC_REFERENCE_H} reference."
        )
        for model_name, model_summary in kinematic_fullva.get("models", {}).items():
            counts = model_summary["constraint_type_counts"]
            lines.append(
                f"  - {model_name}: {model_summary['constraint_count']} constraints "
                f"(DP1={counts['DP1']}, DP2={counts['DP2']}, CD={counts['CD']}, D={counts['D']}), "
                f"max Phi/vel/acc residuals {model_summary['max_position_constraint_norm']:.3e}/"
                f"{model_summary['max_velocity_constraint_norm']:.3e}/"
                f"{model_summary['max_acceleration_constraint_norm']:.3e}, max SO(3) defect "
                f"{model_summary['max_so3_fro']:.3e}, min sigma "
                f"{model_summary['min_singular_value']:.3e}."
            )
        lines.append(
            "- This is now a local closed-loop FullVA kinematic time solve for the two fully constrained driven "
            "examples. The reaction-multiplier dynamics rows are reported in the following reconstruction block."
        )
        lines.append("")
    reaction_fullva = asme_gate.get("method_runs", {}).get("closed_loop_reaction_dynamics", {})
    if reaction_fullva.get("status") == "ok":
        lines.append(
            "- four_link/slider_crank reaction-dynamics reconstruction: "
            f"{reaction_fullva['mapping_scope']} using `{reaction_fullva['method']}`; multipliers were reconstructed "
            "from the accepted local kinematic FullVA states and checked in translational/rotational Newton-Euler rows."
        )
        for model_name, model_summary in reaction_fullva.get("models", {}).items():
            lines.append(
                f"  - {model_name}: max translational/rotational/full dynamics residuals "
                f"{model_summary['max_trans_dynamics_residual']:.3e}/"
                f"{model_summary['max_rot_dynamics_residual']:.3e}/"
                f"{model_summary['max_dynamics_residual_norm']:.3e}; max multiplier norm "
                f"{model_summary['max_multiplier_norm']:.3e}."
            )
        lines.append(
            "- This supplies the local reaction-multiplier dynamics rows for the driven four_link and slider_crank "
            "closed-loop examples."
        )
        lines.append("")
    for model, entry in asme_gate["models"].items():
        lines.append(
            f"- {model}: v046 baseline present={entry['v046_baseline_present']}, "
            f"constraint checks passed={entry['v046_constraint_checks_passed']}; "
            f"v047 mapping={entry['v047_mapping_status']}; required extension: {entry['required_extension']}."
        )
    lines.append("")
