def v047_pipeline_four_asme_status(asme_gate: dict) -> str:
    runs = asme_gate.get("method_runs", {})
    single_stack_ok = (
        runs.get("single_pendulum_driven_kinematic", {}).get("status") == "ok"
        and runs.get("single_pendulum_driven_absolute_fullva", {}).get("status") == "ok"
        and runs.get("single_pendulum_driven_fullva", {}).get("status") == "ok"
        and runs.get("single_pendulum_reaction_dynamics", {}).get("status") == "ok"
    )
    double_policy_ok = (
        runs.get("double_pendulum", {}).get("status") == "ok"
        and runs.get("double_pendulum_reference_policy", {}).get("status")
        == "accepted_local_reference_v046_floor_diagnostic"
        and runs.get("double_pendulum_v046_reference_floor", {}).get("status") == "reference_floor_halves"
    )
    bridge_ok = runs.get("lower_pair_graph_bridge", {}).get("status") == "ok"
    rank_ok = runs.get("lower_pair_graph_rank_audit", {}).get("status") == "ok"
    kinematic_ok = runs.get("closed_loop_kinematic_fullva", {}).get("status") == "ok"
    reaction_ok = runs.get("closed_loop_reaction_dynamics", {}).get("status") == "ok"
    if single_stack_ok and double_policy_ok and bridge_ok:
        graph_clause = (
            "four-example lower-pair constraint-graph bridge, a full-row-rank Phi_q audit, accepted closed-loop "
            "kinematic FullVA solves for four_link and slider_crank, and accepted reaction-dynamics rows"
            if reaction_ok
            else (
            "four-example lower-pair constraint-graph bridge, a full-row-rank Phi_q audit, and accepted "
            "closed-loop kinematic FullVA solves for four_link and slider_crank"
            if kinematic_ok
            else (
                "four-example lower-pair constraint-graph bridge plus a full-row-rank Phi_q audit"
                if rank_ok
                else "four-example lower-pair constraint-graph bridge"
            )
            )
        )
        pending_clause = (
            "four ASME method rows are accepted; remaining caveats are sparse speed, full TFE stage replacement, and practical sharp-friction coarse-regime order reduction"
            if reaction_ok
            else (
            "local dynamic/reaction-multiplier FullVA rows for the driven closed-loop examples remain unclaimed"
            if kinematic_ok
            else "exact local FullVA closed-loop four-link and slider-crank acceptance evidence is still missing"
            )
        )
        return (
            "v046 baseline ingested; v047 has exact driven kinematic single-pendulum mapping, full "
            "absolute-coordinate driven single FullVA residual, embedded driven single FullVA bridge, "
            "reaction-multiplier reconstruction, partial free-revolute single mapping, accepted double-pendulum "
            "FullVA reference policy, a v046 double comparison diagnostic, a reference-floor halving check, and a "
            f"{graph_clause}; {pending_clause}"
        )
    if single_stack_ok and double_policy_ok:
        return (
            "v046 baseline ingested; v047 has exact driven kinematic single-pendulum mapping, full "
            "absolute-coordinate driven single FullVA residual, embedded driven single FullVA bridge, "
            "reaction-multiplier reconstruction, partial free-revolute single mapping, accepted double-pendulum "
            "FullVA reference policy, a v046 double comparison diagnostic, and a reference-floor halving check; "
            "remaining four-link and slider-crank exact method mappings are still incomplete"
        )
    if runs.get("single_pendulum_driven_kinematic", {}).get("status") == "ok":
        return (
            "v046 baseline ingested; v047 has exact driven kinematic single-pendulum mapping plus partial "
            "free-revolute method-side mapping; remaining exact ASME method mappings are still incomplete"
        )
    if runs.get("single_pendulum", {}).get("status") == "ok":
        return (
            "v046 baseline ingested; v047 has a partial method-side single-pendulum mapping; exact four-example "
            "method mapping is still incomplete"
        )
    return (
        "v046 baseline ingested; v047 single-pendulum method-side mapping was attempted but not accepted; "
        "exact four-example method mapping is still incomplete"
    )


