def v047_sparse_backend_status(experiment: dict, sparse_cost_model: dict | None = None) -> str:
    clauses = []
    row_wins = []
    dense_wins = []
    for case_name, case in experiment.get("cases", {}).items():
        pattern = case["patterns"]["generated_block_jvp_pruned"]
        bench = case["runtime_benchmark"]
        row_over_column = bench["median_row_over_column"]
        dense_over_row = bench["median_dense_over_row"]
        clauses.append(
            f"{case_name}: exact {pattern['nnz']}-entry pattern, {pattern['colors']} column colors, "
            f"{pattern['row_colors']} row colors, median row/column {row_over_column:.3f}x, "
            f"median dense/row {dense_over_row:.3f}x"
        )
        row_wins.append(row_over_column < 1.0)
        dense_wins.append(dense_over_row > 1.0)
    if row_wins and all(row_wins) and all(dense_wins):
        verdict = "row-VJP is a repeated-benchmark sparse speed win"
    elif row_wins and all(row_wins):
        verdict = "row-VJP beats column-JVP in repeated timing but dense jacfwd remains faster; sparse speed remains pending"
    else:
        verdict = "row-VJP reduces seed count but is not a stable runtime win; sparse speed remains pending"
    cost_clause = ""
    if sparse_cost_model and sparse_cost_model.get("cases"):
        max_match = sparse_cost_model.get("max_row_runtime_reduction_needed_to_match_dense", float("nan"))
        max_win = sparse_cost_model.get("max_row_runtime_reduction_needed_for_10pct_dense_win", float("nan"))
        min_colors = sparse_cost_model.get("min_effective_row_colors_at_dense_cost", float("nan"))
        cost_clause = (
            f"; sparse cost model: max row runtime reduction needed to match dense "
            f"{100.0 * max_match:.1f}%, for 10pct dense win {100.0 * max_win:.1f}%, "
            f"minimum dense-equivalent row colors {min_colors:.1f}"
        )
    return verdict + "; " + "; ".join(clauses) + cost_clause


def v047_sharp_friction_status(friction_smoothness: dict, sharp_adaptive: dict, sharp_tol_conv: dict, sharp_fixed_refinement: dict, sharp_deep_refinement: dict, sharp_ultra_refinement: dict, sharp_refinement_cost_envelope: dict) -> str:
    cases = sorted(
        friction_smoothness.get("cases", {}).values(),
        key=lambda item: item["stribeck_velocity"],
        reverse=True,
    )
    if not cases:
        return "friction smoothness sweep missing; sharp-friction order reduction remains unquantified"
    clauses = [
        f"vs={case['stribeck_velocity']:.3g}: position/velocity orders "
        f"{case['position_order']:.3f}/{case['velocity_order']:.3f}"
        for case in cases
    ]
    sharp = min(cases, key=lambda item: item["stribeck_velocity"])
    adaptive_clause = ""
    best_adaptive = sharp_adaptive.get("best_adaptive", {})
    fixed_h001 = sharp_adaptive.get("fixed_h001", {})
    if best_adaptive and fixed_h001:
        value_ratio = (
            best_adaptive["velocity_error"] / max(fixed_h001["velocity_error"], 1.0e-300)
        ) / (
            best_adaptive["runtime_sec"] / max(fixed_h001["runtime_sec"], 1.0e-300)
        )
        adaptive_clause = (
            f"; adaptive step-doubling best velocity error {best_adaptive['velocity_error']:.3e} at "
            f"{best_adaptive['runtime_sec']:.3f}s vs fixed h=0.01 {fixed_h001['velocity_error']:.3e} at "
            f"{fixed_h001['runtime_sec']:.3f}s, value ratio {value_ratio:.3f}"
        )
    tolerance_clause = ""
    if sharp_tol_conv.get("status", "").startswith("ok"):
        tolerance_clause = (
            f"; adaptive tolerance/work fit velocity slopes all/prefix "
            f"{sharp_tol_conv['velocity_tol_slope_all']:.3f}/{sharp_tol_conv['velocity_tol_slope_prefix']:.3f}, "
            f"tail error/tolerance ratios {sharp_tol_conv['tail_velocity_error_ratio']:.3f}/"
            f"{sharp_tol_conv['tail_tolerance_ratio']:.3f}, reference-floor flag "
            f"{sharp_tol_conv['reference_floor_flag']}"
        )
    fixed_refinement_clause = ""
    if sharp_fixed_refinement.get("status"):
        fixed_refinement_clause = (
            f"; fixed refinement h={sharp_fixed_refinement['h_values']} vs "
            f"h={sharp_fixed_refinement['reference_h']}: all/tail position orders "
            f"{sharp_fixed_refinement['position_observed_order_all']:.3f}/"
            f"{sharp_fixed_refinement['position_tail_order']:.3f}, all/tail velocity orders "
            f"{sharp_fixed_refinement['velocity_observed_order_all']:.3f}/"
            f"{sharp_fixed_refinement['velocity_tail_order']:.3f}, status "
            f"{sharp_fixed_refinement['status']}"
        )
    deep_refinement_clause = ""
    if sharp_deep_refinement.get("status"):
        deep_refinement_clause = (
            f"; deep fixed refinement h={sharp_deep_refinement['h_values']} vs "
            f"h={sharp_deep_refinement['reference_h']}: all/tail position orders "
            f"{sharp_deep_refinement['position_observed_order_all']:.3f}/"
            f"{sharp_deep_refinement['position_tail_order']:.3f}, all/tail velocity orders "
            f"{sharp_deep_refinement['velocity_observed_order_all']:.3f}/"
            f"{sharp_deep_refinement['velocity_tail_order']:.3f}, status "
            f"{sharp_deep_refinement['status']}"
        )
    ultra_refinement_clause = ""
    if sharp_ultra_refinement.get("status"):
        ultra_refinement_clause = (
            f"; ultra fixed refinement h={sharp_ultra_refinement['h_values']} vs "
            f"h={sharp_ultra_refinement['reference_h']}: all/tail position orders "
            f"{sharp_ultra_refinement['position_observed_order_all']:.3f}/"
            f"{sharp_ultra_refinement['position_tail_order']:.3f}, all/tail velocity orders "
            f"{sharp_ultra_refinement['velocity_observed_order_all']:.3f}/"
            f"{sharp_ultra_refinement['velocity_tail_order']:.3f}, status "
            f"{sharp_ultra_refinement['status']}"
        )
    cost_envelope_clause = ""
    if sharp_refinement_cost_envelope.get("status") == "sharp_refinement_cost_quantified_ultra_high_order_cost_caveat":
        cost_envelope_clause = (
            f"; sharp refinement cost envelope uses baseline h={sharp_refinement_cost_envelope['baseline_h']:.3g} "
            f"and finds finest high-order h={sharp_refinement_cost_envelope['min_high_order_finest_h']:.4g}; "
            f"runtime/step/Newton factors reach "
            f"{sharp_refinement_cost_envelope['max_runtime_factor_vs_h001']:.2f}x/"
            f"{sharp_refinement_cost_envelope['max_accepted_steps_factor_vs_h001']:.1f}x/"
            f"{sharp_refinement_cost_envelope['max_newton_iteration_factor_vs_h001']:.1f}x, "
            f"with max velocity-error reduction "
            f"{sharp_refinement_cost_envelope['max_velocity_error_reduction_vs_h001']:.2e}x; "
            "therefore the remaining sharp-friction caveat is practical cost/coarse-regime behavior"
        )
    if sharp_ultra_refinement.get("status") == "ultra_high_order_recovered":
        verdict = "smoothness sweep shows coarse sharp-friction order reduction, but ultra fixed refinement recovers high order at the finer tested scale; practical sharp-friction caveat remains open"
    elif sharp["position_order"] >= 5.5 and sharp["velocity_order"] >= 5.5:
        verdict = "smoothness sweep shows high order even at the sharpest tested Brown-McPhee width"
    else:
        verdict = "smoothness sweep quantifies order reduction as Brown-McPhee regularization sharpens; sharp-friction caveat remains open"
    return (
        verdict
        + "; "
        + "; ".join(clauses)
        + adaptive_clause
        + tolerance_clause
        + fixed_refinement_clause
        + deep_refinement_clause
        + ultra_refinement_clause
        + cost_envelope_clause
    )


