def update_summary_with_targeted_lower_pair_audit(
    summary_key: str,
    audit: dict,
    marker: str,
    endpoint_clause: str,
) -> None:
    summary_path = RESULTS / "summary_v047.json"
    summary_updated = False
    if summary_path.exists():
        with summary_path.open("r", encoding="utf-8") as f:
            summary = json.load(f)
        gate = summary.setdefault("pipeline_gate_status", {})
        endpoint_text = gate.get("endpoint_velocity_closure", "")
        if marker in endpoint_text:
            endpoint_text = "; ".join(
                part for part in endpoint_text.split("; ") if marker not in part
            )
        if "; independent full TFE stage replacement remains pending" in endpoint_text:
            gate["endpoint_velocity_closure"] = endpoint_text.replace(
                "; independent full TFE stage replacement remains pending",
                f"{endpoint_clause}; independent full TFE stage replacement remains pending",
            )
        else:
            gate["endpoint_velocity_closure"] = f"{endpoint_text}{endpoint_clause}"
        audit["summary_updated"] = True
        summary[summary_key] = json_safe(audit)
        with summary_path.open("w", encoding="utf-8") as f:
            json.dump(json_safe(summary), f, indent=2, sort_keys=True)
        summary_updated = True
    audit["summary_updated"] = summary_updated
    artifact_json = audit.get("artifact_json")
    if artifact_json:
        artifact_path = HERE / str(artifact_json)
        with artifact_path.open("w", encoding="utf-8") as f:
            json.dump(json_safe(audit), f, indent=2, sort_keys=True)


